window.DIAS_B2 = [
{
 d:1, tema:"Lo que pudo haber sido", objetivo:"Hablar de pasados imposibles con el tercer condicional.",
 chunks:["If I had known, I would have told you.","We would have missed the flight if we had left later.","I could have helped if you had asked.","Had I known, things would be different.","It would never have happened otherwise.","If only I had listened to her."],
 vocab:["regret|arrepentirse|I regret not calling.","hindsight|retrospectiva|With hindsight, it was obvious.","otherwise|de otro modo|Otherwise it would have failed.","narrowly|por poco|We narrowly avoided it.","end up|acabar|We would have ended up lost.","blame|culpar|Do not blame yourself.","warn|avisar|I warned you about it.","spot|detectar|Nobody spotted the error.","in time|a tiempo|We got there just in time.","turn down|rechazar|I turned down the offer."],
 dial:{t:"Looking back on a decision", l:[
  "A|Do you ever regret turning down that job?|¿Te arrepientes alguna vez de haber rechazado aquel trabajo?",
  "B|Sometimes. If I had accepted, I would be in Berlin now.|A veces. Si lo hubiera aceptado, ahora estaría en Berlín.",
  "A|Would you have been happier?|¿Habrías sido más feliz?",
  "B|Honestly? I do not think I would have lasted a year.|¿Sinceramente? No creo que hubiera durado un año.",
  "A|Why do you say that?|¿Por qué lo dices?",
  "B|If the salary had been the only issue, I would have gone.|Si el sueldo hubiera sido el único problema, habría ido.",
  "A|So it was the company culture?|¿Así que era la cultura de la empresa?",
  "B|Exactly. With hindsight, I made the right call.|Exacto. Visto con perspectiva, acerté.",
  "A|I would have done the same.|Yo habría hecho lo mismo.",
  "B|If only they had offered it two years earlier.|Ojalá me lo hubieran ofrecido dos años antes."]},
 esc:[{q:"What did B turn down?",o:["A promotion","A job in Berlin","A transfer"],k:1},
      {q:"What was the real problem?",o:["The salary","The company culture","The city"],k:1},
      {q:"Does B regret the decision?",o:["Completely","No, it was the right call","Partly, because of money"],k:1}],
 gram:{t:"Third conditional", idea:"<b>If + past perfect, … would have + participio</b>. Habla de un pasado que no ocurrió y de su consecuencia imaginaria. Variantes: <i>could have / might have</i> para posibilidad. Inversión formal: <b>Had I known…</b> (sin <i>if</i>).",
  ej:["If I had known, I would have told you.","We would have missed the flight if we had left later.","I could have helped if you had asked.","Had I known, I would have acted differently.","They might have won if they had trained.","If only I had listened."],
  nota:"Nunca <i>If I would have known</i>. El <i>would</i> va solo en la consecuencia, jamás tras <i>if</i>.",
  drill:[["If I ___ (know), I would have told you.","had known"],["We ___ (miss) the flight if we had left later.","would have missed"],["I could ___ (help) if you had asked.","have helped"],["___ I known, I would have acted differently.","Had"]]},
 prod:{habla:"Analiza en voz alta tres decisiones de tu vida: qué habría pasado si hubieras elegido lo contrario.",
  escribe:"Escribe 6 frases con tercer condicional sobre decisiones pasadas.",
  modelo:"If I had accepted that job in Berlin five years ago, my whole career would have been different. I would probably have earned more, but I do not think I would have lasted a year there. If the salary had been the only issue, I would have gone without hesitating. With hindsight, the company culture would have made me miserable. Had they offered it two years earlier, when I had no mortgage, I might have said yes. I could have made a serious mistake if I had listened only to the money.",
  tr:["Si lo hubiera sabido, te lo habría dicho.","If I had known, I would have told you."]},
 test:[
  {q:"If I ___ , I would have told you.",o:["knew","had known","would know","have known"],k:1},
  {q:"We ___ the flight if we had left later.",o:["would miss","would have missed","had missed","will miss"],k:1},
  {q:"Elige la incorrecta:",o:["If I had known, I would have gone.","If I would have known, I would have gone.","Had I known, I would have gone.","I could have gone if I had known."],k:1},
  {q:"___ I known, I would have acted differently.",o:["If","Had","Would","Should"],k:1},
  {q:"'With hindsight' significa…",o:["con perspectiva, a posteriori","con dificultad","con vistas","por detrás"],k:0},
  {q:"They ___ won if they had trained.",o:["might have","might had","may had","would had"],k:0},
  {q:"'If only I had listened' expresa…",o:["una condición futura","arrepentimiento","una orden","una duda"],k:1},
  {q:"'Turn down an offer' significa…",o:["bajar la oferta","rechazarla","aceptarla con reservas","aplazarla"],k:1}]
},
{
 d:2, tema:"Deseos y lamentos", objetivo:"Usar wish, if only y condicionales mixtos.",
 chunks:["I wish I spoke better German.","I wish I had studied harder.","If only he would listen.","I would rather you did not tell her.","It is time we left.","If I had saved more, I would be able to buy it now."],
 vocab:["wish|desear / ojalá|I wish I knew.","if only|ojalá|If only I could.","would rather|preferir que|I would rather you stayed.","it is time|ya va siendo hora|It is time we left.","long for|anhelar|I long for a break.","miss out on|perderse algo|I missed out on the chance.","take for granted|dar por sentado|Do not take it for granted.","settle for|conformarse con|I will not settle for less.","dwell on|darle vueltas a|Do not dwell on it.","move on|pasar página|It is time to move on."],
 dial:{t:"A late-night conversation", l:[
  "A|I wish I had studied languages at university.|Ojalá hubiera estudiado idiomas en la universidad.",
  "B|You still can. It is not too late.|Todavía puedes. No es tarde.",
  "A|If I had started then, I would be fluent now.|Si hubiera empezado entonces, ahora sería fluido.",
  "B|Maybe. Or you would have given up.|Puede. O lo habrías dejado.",
  "A|I wish you would stop being so realistic.|Ojalá dejaras de ser tan realista.",
  "B|Sorry. But I would rather you looked forward.|Perdona. Pero preferiría que mirases hacia delante.",
  "A|It is time I made a proper plan, I suppose.|Supongo que ya va siendo hora de hacer un plan en serio.",
  "B|Exactly. Do not dwell on what you missed out on.|Exacto. No le des vueltas a lo que te perdiste.",
  "A|If only I had more free time.|Ojalá tuviera más tiempo libre.",
  "B|Nobody has. You make it or you do not.|Nadie lo tiene. O lo sacas o no."]},
 esc:[{q:"What does A regret?",o:["Not studying languages","Not travelling","Choosing the wrong job"],k:0},
      {q:"What does B suggest?",o:["Looking forward","Going back to university","Giving up"],k:0},
      {q:"What does A wish about time?",o:["To have more free time","To work less","To sleep more"],k:0}],
 gram:{t:"wish / if only y condicionales mixtos", idea:"<b>wish + past simple</b> = deseo presente irreal (<i>I wish I knew</i>). <b>wish + past perfect</b> = lamento del pasado (<i>I wish I had studied</i>). <b>wish + would</b> = queja sobre la conducta ajena (<i>I wish he would listen</i>). Mixtos: <i>If I had saved more (pasado), I would be able to buy it now (presente)</i>.",
  ej:["I wish I spoke German.","I wish I had studied harder.","If only he would listen.","I would rather you did not tell her.","It is time we left.","If I had saved more, I would be rich now."],
  nota:"<i>I wish I would…</i> no existe: no puedes quejarte de tu propia conducta con <i>would</i>. Y tras <i>It is time</i> y <i>would rather + sujeto</i> va past simple con valor presente.",
  drill:[["I wish I ___ (speak) German.","spoke"],["I wish I ___ (study) harder.","had studied"],["If only he ___ listen!","would"],["It is time we ___ (leave).","left"]]},
 prod:{habla:"Expresa cinco deseos y tres lamentos reales sobre tu vida, y una queja sobre otra persona.",
  escribe:"Escribe 6 frases con wish, if only y condicionales mixtos.",
  modelo:"I wish I had studied languages seriously when I was twenty. If I had started then, I would be completely fluent by now. I also wish I spoke German, because half my clients are in Berlin. If only my company would pay for proper classes instead of an app. I would rather my colleagues did not schedule meetings at eight in the morning, but that is another story. It is time I stopped complaining and made a real plan.",
  tr:["Ojalá hubiera estudiado más.","I wish I had studied harder."]},
 test:[
  {q:"I wish I ___ German.",o:["speak","spoke","would speak","had spoken"],k:1,exp:"Deseo presente → past simple"},
  {q:"I wish I ___ harder at school.",o:["studied","had studied","would study","study"],k:1},
  {q:"If only he ___ listen!",o:["will","would","did","had"],k:1},
  {q:"It is time we ___ .",o:["leave","left","will leave","are leaving"],k:1},
  {q:"Elige la incorrecta:",o:["I wish I would be taller.","I wish I were taller.","I wish he would help.","I wish I had helped."],k:0},
  {q:"I would rather you ___ her.",o:["do not tell","did not tell","will not tell","have not told"],k:1},
  {q:"'Dwell on' significa…",o:["habitar","darle vueltas a algo","profundizar bien","posponer"],k:1},
  {q:"'Miss out on' significa…",o:["perderse una oportunidad","echar de menos","fallar","salir fuera"],k:0}]
},
{
 d:3, tema:"Reproches y suposiciones", objetivo:"Dominar los modales perfectos.",
 chunks:["You should have told me earlier.","She must have left already.","It can't have been him.","They might have got lost.","I needn't have worried.","You could have warned me."],
 vocab:["needn't have|no hacía falta que|I needn't have worried.","ought to have|debería haber|You ought to have called.","bound to|seguro que|He was bound to find out.","let alone|ni mucho menos|I cannot walk, let alone run.","after all|al fin y al cabo|After all, he is new.","in fairness|en justicia|In fairness, he tried.","overlook|pasar por alto|I overlooked that detail.","assume|dar por hecho|I assumed you knew.","point out|señalar|She pointed out the error.","hold against|reprochar|I do not hold it against you."],
 dial:{t:"After a mistake at work", l:[
  "A|The client noticed the error before we did.|El cliente vio el error antes que nosotros.",
  "B|You should have checked the figures twice.|Deberías haber revisado las cifras dos veces.",
  "A|I did. Someone must have changed the file.|Lo hice. Alguien debe de haber cambiado el archivo.",
  "B|It can't have been Marta, she was away.|No puede haber sido Marta, estaba fuera.",
  "A|Then it might have been an automatic update.|Entonces puede que fuera una actualización automática.",
  "B|You ought to have saved a copy.|Deberías haber guardado una copia.",
  "A|I did, actually. So I needn't have panicked.|De hecho la guardé. Así que no hacía falta que me agobiara.",
  "B|You could have said that ten minutes ago.|Podrías haberlo dicho hace diez minutos.",
  "A|In fairness, you did not ask.|En justicia, no me lo preguntaste.",
  "B|Fine. Let us fix it and move on.|Vale. Arreglémoslo y sigamos."]},
 esc:[{q:"Who noticed the error first?",o:["Marta","The client","The manager"],k:1},
      {q:"Why can it not have been Marta?",o:["She was away","She never touches files","She is new"],k:0},
      {q:"Did A have a backup?",o:["No","Yes","He is not sure"],k:1}],
 gram:{t:"Modales perfectos", idea:"<b>should/ought to have + participio</b> = reproche o algo que no se hizo. <b>must have</b> = deducción casi segura. <b>can't have</b> = deducción negativa. <b>might/may/could have</b> = posibilidad. <b>needn't have</b> = se hizo pero no hacía falta. <b>didn't need to</b> = no hacía falta y no se hizo.",
  ej:["You should have told me.","She must have left already.","It can't have been him.","They might have got lost.","I needn't have worried.","You could have warned me."],
  nota:"Matiz fino: <i>I needn't have bought bread</i> (lo compré, sobraba) frente a <i>I didn't need to buy bread</i> (no hacía falta, así que no lo compré).",
  drill:[["You ___ (should / tell) me earlier.","should have told"],["She ___ (must / leave) already.","must have left"],["It ___ (can't / be) him.","can't have been"],["I ___ (needn't / worry).","needn't have worried"]]},
 prod:{habla:"Analiza un error reciente: qué debería haber hecho, qué debe de haber pasado y qué no hacía falta.",
  escribe:"Escribe 6 frases con modales perfectos.",
  modelo:"The client spotted the error before we did, which should never have happened. I should have checked the figures a second time before sending the file. Somebody must have overwritten the document during the afternoon. It can't have been Marta, because she was away all week. It might have been an automatic update, although nobody has confirmed that yet. In the end I needn't have panicked, since I had saved a copy that morning.",
  tr:["Deberías habérmelo dicho antes.","You should have told me earlier."]},
 test:[
  {q:"You ___ me earlier.",o:["should tell","should have told","should told","must tell"],k:1},
  {q:"She ___ already. (deducción segura)",o:["must leave","must have left","must had left","should have left"],k:1},
  {q:"It ___ him, he was in Rome.",o:["mustn't have been","can't have been","could not be","may not been"],k:1},
  {q:"'I needn't have worried' significa…",o:["No hacía falta preocuparme (pero lo hice)","No me preocupé","No debo preocuparme","No quise preocuparme"],k:0},
  {q:"They ___ got lost. (posible)",o:["might have","might had","must had","should has"],k:0},
  {q:"'Ought to have' equivale a…",o:["must have","should have","can have","would have"],k:1},
  {q:"'Let alone' significa…",o:["dejar solo","ni mucho menos / y menos aún","permitir","aparte de"],k:1},
  {q:"'Point out' significa…",o:["apuntar fuera","señalar / hacer notar","salir apuntando","excluir"],k:1}]
},
{
 d:4, tema:"Énfasis por inversión", objetivo:"Dar fuerza y elegancia a tus frases invirtiendo el orden.",
 chunks:["Never have I seen anything like it.","Not only did he apologise, he also paid.","Rarely does she complain.","Under no circumstances should you sign it.","Only then did I understand.","No sooner had we arrived than it started to rain."],
 vocab:["rarely|rara vez|Rarely does he call.","seldom|pocas veces|Seldom do we agree.","hardly ever|casi nunca|Hardly ever does it snow.","no sooner|apenas|No sooner had we left…","under no circumstances|bajo ningún concepto|Under no circumstances.","not until|no hasta que|Not until later did I know.","at no point|en ningún momento|At no point did he lie.","little did I know|poco imaginaba yo|Little did I know.","only then|solo entonces|Only then did it make sense.","by no means|de ninguna manera|By no means is it easy."],
 dial:{t:"An unexpected outcome", l:[
  "A|How did the negotiation go?|¿Cómo fue la negociación?",
  "B|Never have I seen a client change his mind so fast.|Nunca había visto a un cliente cambiar de opinión tan rápido.",
  "A|In your favour?|¿A tu favor?",
  "B|Not only did he accept the price, he also extended the contract.|No solo aceptó el precio, también amplió el contrato.",
  "A|That is unusual.|Eso es raro.",
  "B|Rarely does anything go that smoothly.|Rara vez sale algo tan rodado.",
  "A|What convinced him?|¿Qué le convenció?",
  "B|Only when I showed the data did he take it seriously.|Solo cuando le enseñé los datos se lo tomó en serio.",
  "A|So the report was worth the effort.|Así que el informe mereció el esfuerzo.",
  "B|By no means was it wasted, no.|De ninguna manera fue en balde, no."]},
 esc:[{q:"What did the client do?",o:["Accepted and extended","Rejected the price","Asked for time"],k:0},
      {q:"What convinced him?",o:["The price","The data","A colleague"],k:1},
      {q:"Was the report worth it?",o:["No","Definitely yes","Partly"],k:1}],
 gram:{t:"Inversión enfática", idea:"Cuando una expresión negativa o restrictiva abre la frase, se invierte sujeto y auxiliar como en una pregunta: <b>Never have I seen…</b>, <b>Not only did he apologise…</b>, <b>Rarely does she complain</b>, <b>Under no circumstances should you…</b>, <b>No sooner had we arrived than…</b>, <b>Only then did I understand</b>.",
  ej:["Never have I seen anything like it.","Not only did he apologise, he also paid.","Rarely does she complain.","Under no circumstances should you sign.","No sooner had we arrived than it rained.","Little did I know what was coming."],
  nota:"Si no hay auxiliar, aparece <b>do/does/did</b>: <i>Rarely does she complain</i>, nunca <i>Rarely she complains</i>. Es un recurso de registro formal o dramático, no de conversación casual.",
  drill:[["Never ___ I seen anything like it.","have"],["Not only ___ he apologise, he also paid.","did"],["Rarely ___ she complain.","does"],["No sooner ___ we arrived than it rained.","had"]]},
 prod:{habla:"Cuenta un logro profesional usando cinco inversiones enfáticas.",
  escribe:"Escribe 6 frases con inversión.",
  modelo:"Never have I seen a negotiation turn around so quickly. Not only did the client accept our price, he also extended the contract by two years. Rarely does a meeting of that kind end with both sides satisfied. Only when I showed him the comparative data did he take the proposal seriously. Under no circumstances would I have agreed to his first offer. By no means was the effort of preparing that report wasted.",
  tr:["Nunca había visto nada igual.","Never have I seen anything like it."]},
 test:[
  {q:"Never ___ I seen anything like it.",o:["have","had","do","did"],k:0},
  {q:"Not only ___ he apologise, he also paid.",o:["does","did","has","was"],k:1},
  {q:"Rarely ___ she complain.",o:["do","does","is","has"],k:1},
  {q:"Elige la correcta:",o:["Rarely she complains.","Rarely does she complain.","Rarely complains she.","Rarely she does complain."],k:1},
  {q:"No sooner ___ we arrived than it rained.",o:["have","had","did","were"],k:1},
  {q:"'Under no circumstances' va seguido de…",o:["orden normal","inversión","gerundio","infinitivo"],k:1},
  {q:"'Little did I know' significa…",o:["Sabía poco","Poco imaginaba yo","Apenas supe","Sé poco"],k:1},
  {q:"'By no means' significa…",o:["por medio de nada","de ninguna manera","sin medios","por poco"],k:1}]
},
{
 d:5, tema:"Poner el foco", objetivo:"Reorganizar la frase para destacar lo importante.",
 chunks:["What I need is more time.","It was Marta who suggested it.","The thing that bothers me is the delay.","All I want is a clear answer.","What happened was that the file was corrupted.","It is the price that worries me, not the quality."],
 vocab:["the thing is|la cuestión es|The thing is, we are late.","the point is|el caso es|The point is, it works.","all I want|lo único que quiero|All I want is clarity.","what matters|lo que importa|What matters is the result.","as far as … goes|en cuanto a|As far as cost goes.","in terms of|en términos de|In terms of quality.","when it comes to|en lo que respecta a|When it comes to money.","the fact that|el hecho de que|The fact that he lied.","rather than|más que|Speed rather than quality.","let alone|y menos aún|Let alone finish it."],
 dial:{t:"Getting to the point", l:[
  "A|So what exactly is the problem?|¿Cuál es exactamente el problema?",
  "B|What worries me is the timeline, not the budget.|Lo que me preocupa es el calendario, no el presupuesto.",
  "A|It was you who approved those dates.|Fuiste tú quien aprobó esas fechas.",
  "B|True. What I did not know was that the supplier had changed.|Cierto. Lo que yo no sabía era que había cambiado el proveedor.",
  "A|The thing that annoys me is that nobody told us.|Lo que me fastidia es que nadie nos lo dijo.",
  "B|All I want is a realistic date.|Lo único que quiero es una fecha realista.",
  "A|What happened was that the order was placed late.|Lo que pasó es que el pedido se hizo tarde.",
  "B|By whom?|¿Por parte de quién?",
  "A|That is what we need to find out.|Eso es lo que hay que averiguar.",
  "B|When it comes to responsibility, everyone disappears.|En lo que respecta a la responsabilidad, todos desaparecen."]},
 esc:[{q:"What worries B?",o:["The budget","The timeline","The quality"],k:1},
      {q:"What did B not know?",o:["The supplier had changed","The price","The client"],k:0},
      {q:"What happened with the order?",o:["It was cancelled","It was placed late","It was duplicated"],k:1}],
 gram:{t:"Oraciones escindidas (cleft sentences)", idea:"Dos formas de destacar: <b>What-cleft</b> — <i>What I need is more time</i> — y <b>It-cleft</b> — <i>It was Marta who suggested it</i>. También <i>All I want is…</i>, <i>The thing that bothers me is…</i>, <i>The reason why… is that…</i>",
  ej:["What I need is more time.","It was Marta who suggested it.","All I want is a clear answer.","The thing that bothers me is the delay.","What happened was that the file was corrupted.","It is the price that worries me."],
  nota:"Tras <i>What I need is…</i> el verbo va en singular aunque siga un plural: <i>What I need is two more days</i>. Es un recurso oral potentísimo para ganar tiempo y foco a la vez.",
  drill:[["___ I need is more time.","What"],["___ was Marta who suggested it.","It"],["___ I want is a clear answer.","All"],["What happened ___ that the file was corrupted.","was"]]},
 prod:{habla:"Explica un problema laboral destacando cinco elementos distintos con cleft sentences.",
  escribe:"Escribe 6 frases enfáticas con cleft sentences.",
  modelo:"What worries me about this project is the timeline, not the budget. It was the change of supplier that caused the delay, although nobody informed us. The thing that really annoys me is that we found out from the client. All I want at this point is a realistic delivery date. What happened, as far as I can tell, is that the order was placed two weeks late. It is transparency, rather than speed, that we need from now on.",
  tr:["Lo que necesito es más tiempo.","What I need is more time."]},
 test:[
  {q:"___ I need is more time.",o:["That","What","Which","It"],k:1},
  {q:"___ was Marta who suggested it.",o:["That","It","What","There"],k:1},
  {q:"What I need ___ two more days.",o:["are","is","were","have"],k:1,exp:"El verbo concuerda con What"},
  {q:"___ I want is a clear answer.",o:["All","Every","Whole","Any"],k:0},
  {q:"'The thing is…' sirve para…",o:["cambiar de tema","introducir el punto clave","preguntar","negar"],k:1},
  {q:"'When it comes to money…' significa…",o:["cuando llega el dinero","en lo que respecta al dinero","cuando venga el dinero","llegando al dinero"],k:1},
  {q:"It is the price ___ worries me.",o:["what","that","which is","who"],k:1},
  {q:"'Rather than' significa…",o:["más bien que / en lugar de","antes de","bastante que","preferible"],k:0}]
},
{
 d:6, tema:"Frases compactas", objetivo:"Comprimir información con cláusulas de participio.",
 chunks:["Having finished the report, I went home.","Built in 1902, the factory is now a museum.","Not knowing what to say, he left.","Being the youngest, she was ignored.","Once completed, the form must be signed.","Faced with the evidence, he admitted everything."],
 vocab:["having done|habiendo hecho|Having done that, we left.","faced with|ante|Faced with the facts.","given|dado que|Given the situation.","provided|siempre que|Provided it is legal.","regarding|en cuanto a|Regarding your email.","including|incluyendo|Including all costs.","followed by|seguido de|Followed by a debate.","based on|basado en|Based on the data.","compared with|comparado con|Compared with last year.","despite having|a pesar de haber|Despite having tried."],
 dial:{t:"Presenting a case", l:[
  "A|How would you summarise the report?|¿Cómo resumirías el informe?",
  "B|Based on the data, demand has fallen twelve per cent.|Según los datos, la demanda ha caído un doce por ciento.",
  "A|And the causes?|¿Y las causas?",
  "B|Having analysed the market, we identified three.|Tras analizar el mercado, identificamos tres.",
  "A|Which is the most serious?|¿Cuál es la más grave?",
  "B|Compared with last year, prices have risen sharply.|Comparado con el año pasado, los precios han subido con fuerza.",
  "A|What do you recommend?|¿Qué recomiendas?",
  "B|Given the situation, we should delay the launch.|Dada la situación, deberíamos retrasar el lanzamiento.",
  "A|Faced with those numbers, I agree.|Ante esos números, estoy de acuerdo.",
  "B|Once approved, the new plan takes six weeks.|Una vez aprobado, el nuevo plan lleva seis semanas."]},
 esc:[{q:"How much has demand fallen?",o:["Two per cent","Twelve per cent","Twenty per cent"],k:1},
      {q:"What is recommended?",o:["Launching now","Delaying the launch","Cancelling"],k:1},
      {q:"How long does the new plan take?",o:["Six weeks","Six months","Two weeks"],k:0}],
 gram:{t:"Cláusulas de participio", idea:"Sustituyen a una oración subordinada cuando el sujeto es el mismo. <b>-ing</b> (activo): <i>Not knowing what to say, he left</i>. <b>Having + participio</b> (anterioridad): <i>Having finished, I left</i>. <b>Participio pasado</b> (pasivo): <i>Built in 1902, the factory…</i> Introductores: <i>Once, When, While, Given, Faced with, Based on</i>.",
  ej:["Having finished the report, I went home.","Built in 1902, the factory is now a museum.","Not knowing what to say, he left.","Once completed, the form must be signed.","Faced with the evidence, he confessed.","Given the situation, we should wait."],
  nota:"El sujeto de las dos partes debe coincidir. <i>Walking down the street, the building looked strange</i> es un error clásico: el edificio no caminaba.",
  drill:[["___ (having / finish) the report, I went home.","Having finished"],["___ (build) in 1902, the factory is now a museum.","Built"],["Not ___ (know) what to say, he left.","knowing"],["___ the situation, we should wait.","Given"]]},
 prod:{habla:"Resume un informe o una noticia en dos minutos usando cinco cláusulas de participio.",
  escribe:"Escribe 6 frases con cláusulas de participio.",
  modelo:"Based on the figures from the last quarter, demand has fallen by twelve per cent. Having analysed the market for three months, we have identified three main causes. Compared with the same period last year, raw material prices have risen sharply. Faced with those numbers, the board decided to postpone the launch. Given the current uncertainty, this seems the only sensible option. Once approved, the revised plan will take six weeks to implement.",
  tr:["Tras terminar el informe, me fui a casa.","Having finished the report, I went home."]},
 test:[
  {q:"___ the report, I went home.",o:["Having finished","Having finish","Have finished","Finished having"],k:0},
  {q:"___ in 1902, the factory is now a museum.",o:["Building","Built","Having built","To build"],k:1},
  {q:"Not ___ what to say, he left.",o:["know","knowing","known","to know"],k:1},
  {q:"Elige la frase mal construida:",o:["Walking home, I saw an old friend.","Walking home, the building looked strange.","Having eaten, we left.","Given the delay, we waited."],k:1},
  {q:"'Given the situation' significa…",o:["dada la situación","dando la situación","regalada la situación","situado en"],k:0},
  {q:"'Faced with' significa…",o:["con cara de","ante / enfrentado a","de frente","cara a cara"],k:1},
  {q:"Once ___ , the form must be signed.",o:["completing","completed","complete it","to complete"],k:1},
  {q:"'Based on the data' significa…",o:["basado en los datos","con base de datos","bajo los datos","fundado el dato"],k:0}]
},
{
 d:7, tema:"REPASO · Debatir con argumentos", objetivo:"Sostener una postura, rebatir y concluir.",
 chunks:["There is a strong case for reform.","The evidence suggests otherwise.","Admittedly, there are drawbacks.","That argument does not hold up.","On balance, the benefits outweigh the costs.","Let me put it another way."],
 vocab:["a strong case for|argumentos sólidos a favor|A strong case for change.","drawback|inconveniente|The main drawback is cost.","outweigh|pesar más que|Benefits outweigh risks.","on balance|en conjunto|On balance, it works.","hold up|sostenerse|That argument does not hold up.","undermine|socavar|That undermines the claim.","evidence|pruebas|The evidence is clear.","assumption|suposición|That is an assumption.","valid|válido|A valid point.","dismiss|descartar|We cannot dismiss it."],
 dial:{t:"A debate about city centres", l:[
  "A|There is a strong case for banning cars in the centre.|Hay argumentos sólidos para prohibir los coches en el centro.",
  "B|Admittedly, pollution would fall. But shops would suffer.|Es cierto que bajaría la contaminación. Pero las tiendas sufrirían.",
  "A|The evidence from other cities suggests otherwise.|Los datos de otras ciudades sugieren lo contrario.",
  "B|Those cities are not comparable.|Esas ciudades no son comparables.",
  "A|That argument does not really hold up.|Ese argumento no se sostiene mucho.",
  "B|Why not?|¿Por qué no?",
  "A|Because footfall rose in every case studied.|Porque el número de visitantes subió en todos los casos estudiados.",
  "B|Granted. Still, the transition would be painful.|Concedido. Aun así, la transición sería dolorosa.",
  "A|On balance, the benefits outweigh the costs.|En conjunto, los beneficios pesan más que los costes.",
  "B|I would not dismiss the concerns of small businesses.|Yo no descartaría las preocupaciones de los pequeños comercios."]},
 esc:[{q:"What is A defending?",o:["Banning cars in the centre","More parking","Higher taxes"],k:0},
      {q:"What is B's main concern?",o:["Pollution","Small businesses","Noise"],k:1},
      {q:"What does the evidence show?",o:["Footfall rose","Shops closed","No change"],k:0}],
 gram:{t:"Estructura del argumento", idea:"Secuencia: <b>tesis</b> (<i>There is a strong case for…</i>) → <b>evidencia</b> (<i>The evidence suggests…</i>) → <b>concesión</b> (<i>Admittedly / Granted / It is true that…</i>) → <b>refutación</b> (<i>However / That said / That argument does not hold up</i>) → <b>conclusión</b> (<i>On balance / All things considered</i>).",
  ej:["There is a strong case for reform.","The evidence suggests otherwise.","Admittedly, there are drawbacks.","That said, the risks are manageable.","On balance, the benefits outweigh the costs.","All things considered, it is worth trying."],
  nota:"Conceder antes de rebatir es lo que separa a un B2 de un B1: <i>Granted, X. However, Y.</i> Reconocer el punto contrario refuerza tu posición, no la debilita.",
  drill:[["There is a strong ___ for reform.","case"],["The evidence ___ otherwise.","suggests"],["___ , there are drawbacks.","Admittedly"],["On ___ , the benefits outweigh the costs.","balance"]]},
 prod:{habla:"Debate dos minutos a favor de prohibir los coches en el centro; concede un punto contrario y refútalo.",
  escribe:"Escribe un argumento de 8 frases con concesión y refutación.",
  modelo:"There is a strong case for restricting private cars in the city centre. The evidence from a dozen European cities suggests that pedestrian areas increase footfall rather than reduce it. Admittedly, the transition period is difficult, and small businesses are right to be worried. However, that concern is usually based on an assumption rather than on data. Granted, cities with poor public transport cannot copy the model directly. That said, our metro network already covers most of the centre. On balance, the environmental and commercial benefits clearly outweigh the short-term costs. All things considered, the question is not whether to do it but how quickly.",
  tr:["En conjunto, los beneficios pesan más que los costes.","On balance, the benefits outweigh the costs."]},
 test:[
  {q:"There is a strong ___ for reform.",o:["case","cause","reason of","point"],k:0},
  {q:"The evidence ___ otherwise.",o:["suggest","suggests","is suggest","suggested to"],k:1},
  {q:"'Admittedly' sirve para…",o:["conceder un punto","negar","concluir","preguntar"],k:0},
  {q:"'Outweigh' significa…",o:["pesar más que","pesar fuera","medir","superar en peso solo físico"],k:0},
  {q:"'That argument does not hold up' significa…",o:["no se sostiene","no aguanta el peso","no se levanta","no retiene"],k:0},
  {q:"'On balance' significa…",o:["en equilibrio","en conjunto, bien pensado","en la balanza","por saldo"],k:1},
  {q:"'Drawback' significa…",o:["retroceso","inconveniente","dibujo","retirada"],k:1},
  {q:"'Undermine' significa…",o:["subrayar","socavar","minar un terreno","reforzar"],k:1}]
},
{
 d:8, tema:"Se dice que…", objetivo:"Usar las pasivas impersonales del inglés periodístico.",
 chunks:["It is said that the company is in trouble.","He is believed to be abroad.","The building is thought to date from 1650.","She is reported to have resigned.","It is widely assumed that prices will fall.","No decision is expected before June."],
 vocab:["be said to|se dice que|He is said to be rich.","be believed to|se cree que|She is believed to be abroad.","be thought to|se piensa que|It is thought to be safe.","be reported to|se informa de que|He is reported to have left.","be expected to|se espera que|Prices are expected to rise.","allegedly|presuntamente|He allegedly lied.","reportedly|según se informa|She reportedly resigned.","claim|afirmar|The company claims otherwise.","deny|negar|He denies everything.","confirm|confirmar|Nothing has been confirmed."],
 dial:{t:"Discussing a news story", l:[
  "A|Have you read about the takeover?|¿Has leído lo de la absorción?",
  "B|It is said that negotiations started in January.|Se dice que las negociaciones empezaron en enero.",
  "A|Is the price known?|¿Se sabe el precio?",
  "B|It is believed to be around four hundred million.|Se cree que ronda los cuatrocientos millones.",
  "A|And the director?|¿Y el director?",
  "B|He is reported to have resigned last week.|Según se informa, dimitió la semana pasada.",
  "A|Has anything been confirmed?|¿Se ha confirmado algo?",
  "B|Nothing official. The company denies everything.|Nada oficial. La empresa lo niega todo.",
  "A|When will we know?|¿Cuándo se sabrá?",
  "B|No announcement is expected before June.|No se espera ningún anuncio antes de junio."]},
 esc:[{q:"When did negotiations reportedly start?",o:["January","June","Last week"],k:0},
      {q:"What is the estimated price?",o:["Forty million","Four hundred million","Four billion"],k:1},
      {q:"What does the company say?",o:["It confirms","It denies everything","No comment"],k:1}],
 gram:{t:"Pasivas impersonales", idea:"Dos estructuras equivalentes: <b>It is said/believed/thought that + frase</b> y <b>Subject + is said/believed to + infinitivo</b>. Para el pasado, <b>to have + participio</b>: <i>He is believed to have left</i>. Adverbios equivalentes: <i>allegedly, reportedly, supposedly</i>.",
  ej:["It is said that the company is in trouble.","The company is said to be in trouble.","He is believed to be abroad.","She is reported to have resigned.","It is widely assumed that prices will fall.","No decision is expected before June."],
  nota:"Este registro es el del periodismo y los informes: distancia al autor de la afirmación. En una conversación normal se diría simplemente <i>Apparently…</i> o <i>People say…</i>",
  drill:[["It is ___ that the company is in trouble.","said"],["He is believed ___ (be) abroad.","to be"],["She is reported ___ (resign).","to have resigned"],["No decision ___ (expect) before June.","is expected"]]},
 prod:{habla:"Resume tres noticias recientes usando cinco pasivas impersonales.",
  escribe:"Escribe una noticia de 6 frases con pasivas impersonales.",
  modelo:"It is said that negotiations over the takeover began as early as January. The final price is believed to be in the region of four hundred million euros. The managing director is reported to have resigned last Thursday, although the company has not confirmed it. It is widely assumed that at least two hundred jobs will be affected. Nothing official is expected to be announced before June. Sources close to the deal allegedly described the atmosphere as tense.",
  tr:["Se cree que está en el extranjero.","He is believed to be abroad."]},
 test:[
  {q:"It is ___ that prices will fall.",o:["say","said","saying","says"],k:1},
  {q:"He is believed ___ abroad.",o:["be","to be","being","that he is"],k:1},
  {q:"She is reported ___ resigned.",o:["to","to have","having","that she"],k:1},
  {q:"'Allegedly' significa…",o:["alegremente","presuntamente","supuestamente probado","legalmente"],k:1},
  {q:"No decision ___ before June.",o:["expects","is expected","is expecting","expected"],k:1},
  {q:"'The company is said to be in trouble' equivale a…",o:["It says the company is in trouble.","It is said that the company is in trouble.","The company says it is in trouble.","People are said the company."],k:1},
  {q:"'Reportedly' significa…",o:["según se informa","con informe","repetidamente","de forma reportada legalmente"],k:0},
  {q:"The building is thought ___ from 1650.",o:["date","to date","dating","dated"],k:1}]
},
{
 d:9, tema:"Verbos de decir con patrón", objetivo:"Reportar con precisión y matiz según el verbo.",
 chunks:["He accused me of lying.","She admitted making a mistake.","They insisted on paying.","He warned us not to go.","She apologised for being late.","He denied having seen it."],
 vocab:["accuse of|acusar de|He accused me of lying.","admit|admitir|She admitted making a mistake.","insist on|insistir en|They insisted on paying.","warn against|advertir contra|He warned us against it.","apologise for|disculparse por|She apologised for the delay.","deny|negar|He denied taking it.","blame for|culpar de|They blamed me for the error.","congratulate on|felicitar por|He congratulated me on the result.","persuade to|convencer de|She persuaded me to stay.","remind to|recordar que|Remind me to call."],
 dial:{t:"Reporting a difficult meeting", l:[
  "A|How did the meeting end?|¿Cómo acabó la reunión?",
  "B|Badly. The client accused us of missing the deadline.|Mal. El cliente nos acusó de incumplir el plazo.",
  "A|Did anyone admit responsibility?|¿Alguien asumió la responsabilidad?",
  "B|Marta admitted underestimating the workload.|Marta reconoció haber subestimado la carga de trabajo.",
  "A|And the boss?|¿Y el jefe?",
  "B|He denied having approved the original schedule.|Negó haber aprobado el calendario original.",
  "A|That is not true.|Eso no es verdad.",
  "B|I know. I reminded him to check his own emails.|Lo sé. Le recordé que revisara sus propios correos.",
  "A|Brave. How did he react?|Valiente. ¿Cómo reaccionó?",
  "B|He apologised for the confusion and insisted on a review.|Se disculpó por la confusión e insistió en una revisión."]},
 esc:[{q:"What did the client accuse them of?",o:["Poor quality","Missing the deadline","Overcharging"],k:1},
      {q:"What did Marta admit?",o:["Underestimating the workload","Nothing","Lying"],k:0},
      {q:"What did the boss do at the end?",o:["Left","Apologised and insisted on a review","Denied everything again"],k:1}],
 gram:{t:"Patrones de los verbos de reporte", idea:"Cada verbo exige su estructura: <b>+ -ing</b>: admit, deny, suggest, recommend. <b>+ sb of + -ing</b>: accuse. <b>+ sb for + -ing</b>: blame, thank, congratulate (on). <b>+ on + -ing</b>: insist. <b>+ sb to do</b>: persuade, remind, warn, advise, encourage. <b>+ for + -ing</b>: apologise.",
  ej:["He accused me of lying.","She admitted making a mistake.","They insisted on paying.","He warned us not to go.","She apologised for being late.","He persuaded me to stay."],
  nota:"<i>Suggest</i> nunca lleva objeto + infinitivo: no <i>He suggested me to go</i>, sino <b>He suggested that I go</b> o <b>He suggested going</b>.",
  drill:[["He accused me ___ lying.","of"],["She admitted ___ (make) a mistake.","making"],["They insisted ___ paying.","on"],["He persuaded me ___ (stay).","to stay"]]},
 prod:{habla:"Relata una discusión real usando ocho verbos de reporte distintos con su patrón correcto.",
  escribe:"Escribe 6 frases reportando una reunión difícil.",
  modelo:"The client accused us of missing the deadline for the second time this year. Marta admitted underestimating the workload, which was honest of her. Our manager denied having approved the original schedule, although the emails prove otherwise. I reminded him to check his own inbox before the next meeting. In the end he apologised for the confusion and insisted on carrying out a full review. Nobody blamed the design team, fortunately.",
  tr:["Me acusó de mentir.","He accused me of lying."]},
 test:[
  {q:"He accused me ___ lying.",o:["to","of","for","about"],k:1},
  {q:"She admitted ___ a mistake.",o:["to make","making","make","to have make"],k:1},
  {q:"They insisted ___ paying.",o:["in","on","to","for"],k:1},
  {q:"She apologised ___ being late.",o:["of","for","to","about to"],k:1},
  {q:"Elige la incorrecta:",o:["He suggested going.","He suggested that I go.","He suggested me to go.","He recommended waiting."],k:2},
  {q:"He warned us ___ go.",o:["to not","not to","don't","no to"],k:1},
  {q:"They blamed me ___ the error.",o:["of","for","on","to"],k:1},
  {q:"He congratulated me ___ the result.",o:["for","on","of","about"],k:1}]
},
{
 d:10, tema:"Relativas de precisión", objetivo:"Usar relativas explicativas y con preposición.",
 chunks:["The report, which was published yesterday, is damning.","The person to whom I spoke was very helpful.","This is the reason why I called.","He arrived late, which annoyed everyone.","The company for which she works is Swiss.","There were fifty applicants, most of whom were unqualified."],
 vocab:["damning|demoledor|A damning report.","in which case|en cuyo caso|In which case, we wait.","some of whom|algunos de los cuales|Some of whom left.","the extent to which|la medida en que|The extent to which it works.","whereby|por el cual|A system whereby users pay.","hence|de ahí que|Hence the delay.","thereby|con lo cual|Thereby reducing costs.","insofar as|en la medida en que|Insofar as it applies.","notwithstanding|no obstante|Notwithstanding the cost.","albeit|aunque|Effective, albeit slow."],
 dial:{t:"Analysing a report", l:[
  "A|Have you seen the report, which came out yesterday?|¿Has visto el informe, que salió ayer?",
  "B|The one in which they criticise the contract?|¿El que critica el contrato?",
  "A|That one. There were twenty recommendations, most of which we ignored.|Ese. Había veinte recomendaciones, la mayoría de las cuales ignoramos.",
  "B|Which explains the current situation.|Lo cual explica la situación actual.",
  "A|The person to whom I spoke was quite blunt.|La persona con la que hablé fue bastante directa.",
  "B|Was that the auditor?|¿Era la auditora?",
  "A|Yes, whose report is now public.|Sí, cuyo informe ya es público.",
  "B|That is the reason why the board met yesterday.|Esa es la razón por la que el consejo se reunió ayer.",
  "A|They may reject it, in which case we start again.|Pueden rechazarlo, en cuyo caso empezamos de cero.",
  "B|Which would be a disaster.|Lo cual sería un desastre."]},
 esc:[{q:"How many recommendations were there?",o:["Ten","Twenty","Fifty"],k:1},
      {q:"Who did A speak to?",o:["The board","The auditor","The client"],k:1},
      {q:"What happens if the board rejects it?",o:["They start again","Nothing","They resign"],k:0}],
 gram:{t:"Relativas explicativas y con preposición", idea:"Las <b>explicativas</b> van entre comas, no admiten <i>that</i> ni omisión: <i>The report, which was published yesterday, is damning</i>. Con preposición en registro formal: <b>preposición + which/whom</b> (<i>the company for which she works</i>). <b>which</b> puede referirse a toda la frase anterior: <i>He arrived late, which annoyed everyone</i>. Cuantificadores: <i>most of whom, some of which</i>.",
  ej:["The report, which came out yesterday, is damning.","The person to whom I spoke was helpful.","He arrived late, which annoyed everyone.","There were fifty applicants, most of whom were unqualified.","This is the reason why I called.","They may reject it, in which case we start again."],
  nota:"En registro informal la preposición se va al final y <i>whom</i> desaparece: <i>The person I spoke to was helpful</i>. Ambos son correctos; elige según el contexto.",
  drill:[["The report, ___ came out yesterday, is damning.","which"],["The person to ___ I spoke was helpful.","whom"],["He arrived late, ___ annoyed everyone.","which"],["Fifty applicants, most of ___ were unqualified.","whom"]]},
 prod:{habla:"Analiza un documento o una situación laboral usando cinco relativas explicativas.",
  escribe:"Escribe 6 frases con relativas complejas.",
  modelo:"The audit report, which was published yesterday, is frankly damning. It contains twenty recommendations, most of which were already made two years ago. The auditor to whom I spoke last month was surprisingly blunt about the delays. She pointed out that nobody had read the original document, which explains a great deal. The board met on Thursday, the reason why nothing has been announced publicly yet. They may reject the conclusions, in which case the whole process starts again.",
  tr:["El informe, que se publicó ayer, es demoledor.","The report, which was published yesterday, is damning."]},
 test:[
  {q:"The report, ___ came out yesterday, is damning.",o:["that","which","what","who"],k:1},
  {q:"The person to ___ I spoke was helpful.",o:["who","whom","which","that"],k:1},
  {q:"He arrived late, ___ annoyed everyone.",o:["that","which","what","who"],k:1},
  {q:"Fifty applicants, most of ___ were unqualified.",o:["which","whom","who","them"],k:1},
  {q:"Elige la incorrecta:",o:["My brother, who lives in Rome, is a chef.","My brother, that lives in Rome, is a chef.","The book which I read was good.","The book I read was good."],k:1},
  {q:"'In which case' significa…",o:["en qué caso","en cuyo caso","en el caso que","por si acaso"],k:1},
  {q:"'Albeit' significa…",o:["aunque","a pesar","al bies","siempre"],k:0},
  {q:"The company ___ she works is Swiss.",o:["for which","which for","that for","for that"],k:0}]
}
,
{
 d:11, tema:"Futuros de precisión", objetivo:"Proyectar el futuro con matices profesionales.",
 chunks:["By next June I will have been working here for ten years.","The meeting is to be held on Tuesday.","We are on the verge of signing.","The results are due out shortly.","Prices are set to rise again.","It is only a matter of time."],
 vocab:["be to|estar previsto (formal)|The meeting is to be held.","be on the verge of|estar a punto de|On the verge of collapse.","be set to|ir a (previsión)|Prices are set to rise.","be due out|estar previsto que salga|The report is due out.","in the long run|a la larga|In the long run, it pays.","sooner or later|tarde o temprano|Sooner or later it will happen.","a matter of time|cuestión de tiempo|It is a matter of time.","forthcoming|próximo|The forthcoming election.","imminent|inminente|A decision is imminent.","in due course|a su debido tiempo|We will inform you in due course."],
 dial:{t:"Briefing before a merger", l:[
  "A|When is the announcement due?|¿Cuándo está previsto el anuncio?",
  "B|The board is to meet on Tuesday.|El consejo se reunirá el martes.",
  "A|So a decision is imminent.|Así que la decisión es inminente.",
  "B|We are on the verge of signing, yes.|Estamos a punto de firmar, sí.",
  "A|By the end of the year, how many staff will we have?|Para final de año, ¿cuánta plantilla tendremos?",
  "B|About four hundred, once the merger is complete.|Unos cuatrocientos, una vez completada la fusión.",
  "A|And by next June?|¿Y para el próximo junio?",
  "B|By then I will have been running this division for ten years.|Para entonces llevaré diez años dirigiendo esta división.",
  "A|Will prices change?|¿Cambiarán los precios?",
  "B|They are set to rise, but not before autumn.|Está previsto que suban, pero no antes del otoño."]},
 esc:[{q:"When does the board meet?",o:["Monday","Tuesday","Next June"],k:1},
      {q:"How many staff after the merger?",o:["Forty","Four hundred","Four thousand"],k:1},
      {q:"When will prices rise?",o:["Immediately","Not before autumn","Never"],k:1}],
 gram:{t:"Future perfect continuous y futuros formales", idea:"<b>will have been + -ing</b> = duración acumulada hasta un punto futuro (<i>By June I will have been working here for ten years</i>). <b>be to + infinitivo</b> = plan oficial (<i>The meeting is to be held</i>). <b>be set to / be due to / be on the verge of + -ing</b> = previsiones y proximidad.",
  ej:["By next June I will have been working here for ten years.","The meeting is to be held on Tuesday.","We are on the verge of signing.","The report is due out shortly.","Prices are set to rise.","A decision is imminent."],
  nota:"<i>Be to</i> se usa mucho en titulares y en instrucciones formales: <i>Passengers are to remain seated</i>. Suena a norma, no a plan personal.",
  drill:[["By June I ___ (work) here for ten years.","will have been working"],["The meeting ___ to be held on Tuesday.","is"],["We are on the ___ of signing.","verge"],["Prices are ___ to rise.","set"]]},
 prod:{habla:"Proyecta tu vida profesional a uno, cinco y diez años vista usando cuatro futuros distintos.",
  escribe:"Escribe 6 frases sobre el futuro con estructuras avanzadas.",
  modelo:"By next June I will have been working in this studio for ten years, which is hard to believe. The board is to meet on Tuesday to approve the new structure. We are on the verge of signing an agreement with a firm in Lisbon. If it goes ahead, by December we will have opened a second office. Costs are set to rise slightly, although not before the autumn. A final decision is imminent and we will inform the team in due course.",
  tr:["Para junio llevaré diez años trabajando aquí.","By June I will have been working here for ten years."]},
 test:[
  {q:"By June I ___ here for ten years.",o:["will work","will have been working","am working","will be working"],k:1},
  {q:"The meeting ___ to be held on Tuesday.",o:["is","will","has","goes"],k:0},
  {q:"We are on the ___ of signing.",o:["edge","verge","point","border"],k:1},
  {q:"Prices are ___ to rise.",o:["set","put","made","gone"],k:0},
  {q:"'Imminent' significa…",o:["eminente","inminente","importante","inmenso"],k:1},
  {q:"'In due course' significa…",o:["a su debido tiempo","por supuesto","en curso","con retraso"],k:0},
  {q:"'The report is due out shortly' significa…",o:["Está previsto que salga pronto","Se debe acortar","Debe salir fuera","Se retrasa"],k:0},
  {q:"'In the long run' significa…",o:["en la carrera larga","a la larga","corriendo mucho","a lo largo"],k:1}]
},
{
 d:12, tema:"Hablar con cautela", objetivo:"Matizar afirmaciones como un profesional (hedging).",
 chunks:["It would appear that there is a problem.","This may well be the best option.","There is a tendency to overestimate the risk.","It is arguably the most important factor.","The results are somewhat inconclusive.","I would be inclined to wait."],
 vocab:["arguably|posiblemente / se podría decir|Arguably the best.","somewhat|algo, un tanto|Somewhat unclear.","tend to|tender a|People tend to exaggerate.","may well|bien podría|That may well be true.","be inclined to|inclinarse a|I am inclined to agree.","broadly speaking|en términos generales|Broadly speaking, yes.","to some extent|hasta cierto punto|True to some extent.","appear to|parecer|It appears to be working.","suggest|apuntar a|The data suggest a trend.","by and large|en general|By and large, it works."],
 dial:{t:"Presenting uncertain data", l:[
  "A|Are the results conclusive?|¿Son concluyentes los resultados?",
  "B|Not entirely. They are somewhat inconclusive.|No del todo. Son un tanto inconcluyentes.",
  "A|What do they suggest?|¿Qué apuntan?",
  "B|It would appear that demand is stabilising.|Parecería que la demanda se está estabilizando.",
  "A|Would you say the crisis is over?|¿Dirías que la crisis ha terminado?",
  "B|That may well be premature.|Eso bien podría ser prematuro.",
  "A|What would you recommend?|¿Qué recomendarías?",
  "B|I would be inclined to wait another quarter.|Me inclinaría por esperar otro trimestre.",
  "A|Is there any risk in waiting?|¿Hay riesgo en esperar?",
  "B|To some extent, but arguably less than in acting now.|Hasta cierto punto, pero posiblemente menos que en actuar ahora."]},
 esc:[{q:"Are the results conclusive?",o:["Yes, completely","Somewhat inconclusive","Totally negative"],k:1},
      {q:"What does B recommend?",o:["Acting now","Waiting a quarter","Cancelling"],k:1},
      {q:"Is the crisis over?",o:["Yes","Saying so may be premature","Definitely not"],k:1}],
 gram:{t:"Hedging: cautela académica y profesional", idea:"Se atenúa la afirmación con: <b>verbos</b> (<i>appear, seem, suggest, tend to</i>), <b>modales</b> (<i>may, might, could, would</i>), <b>adverbios</b> (<i>arguably, possibly, somewhat, broadly</i>) y <b>fórmulas</b> (<i>It would appear that…, To some extent…, I would be inclined to…</i>).",
  ej:["It would appear that there is a problem.","This may well be the best option.","People tend to overestimate the risk.","It is arguably the most important factor.","The results are somewhat inconclusive.","Broadly speaking, the trend is positive."],
  nota:"En inglés profesional, afirmar sin matizar suena arrogante o poco riguroso. El hedging no es debilidad: es precisión.",
  drill:[["It would ___ that there is a problem.","appear"],["This ___ well be the best option.","may"],["People ___ to overestimate the risk.","tend"],["It is ___ the most important factor.","arguably"]]},
 prod:{habla:"Presenta unos datos ambiguos durante dos minutos sin afirmar nada de forma tajante.",
  escribe:"Escribe 6 frases con hedging sobre una situación incierta.",
  modelo:"The figures for the last quarter are somewhat inconclusive, although the trend appears to be positive. It would seem that demand is stabilising after two difficult years. That said, it may well be premature to describe the crisis as over. Companies in this sector tend to overestimate short-term recoveries. Broadly speaking, I would be inclined to wait another quarter before committing resources. Arguably, the risk of waiting is smaller than the risk of acting on incomplete data.",
  tr:["Parecería que hay un problema.","It would appear that there is a problem."]},
 test:[
  {q:"It would ___ that there is a problem.",o:["appear","appears","appearing","be appear"],k:0},
  {q:"This ___ well be the best option.",o:["may","must","should","can"],k:0},
  {q:"People ___ to overestimate risk.",o:["tends","tend","are tending","tended"],k:1},
  {q:"'Arguably' significa…",o:["discutiblemente / posiblemente","argumentando","con discusión","sin duda"],k:0},
  {q:"'Somewhat' significa…",o:["de algún modo total","un tanto, algo","alguna cosa","en algún sitio"],k:1},
  {q:"'I am inclined to agree' significa…",o:["Me inclino a estar de acuerdo","Me obligan a aceptar","Estoy inclinado","Rechazo"],k:0},
  {q:"'To some extent' significa…",o:["en gran medida","hasta cierto punto","en toda su extensión","sin límite"],k:1},
  {q:"'By and large' significa…",o:["en general","por lo grande","a lo largo","cerca y lejos"],k:0}]
},
{
 d:13, tema:"El inglés del trabajo", objetivo:"Manejar colocaciones y modismos del entorno profesional.",
 chunks:["Let us touch base next week.","We need to think outside the box.","That is not really my call.","Can we take this offline?","We are behind schedule.","Let us play it by ear."],
 vocab:["touch base|ponerse en contacto|Let us touch base on Monday.","my call|mi decisión|That is not my call.","take it offline|tratarlo aparte|Let us take this offline.","behind schedule|con retraso|We are behind schedule.","in the pipeline|en preparación|Two projects in the pipeline.","cut corners|hacer chapuzas por ahorrar|We cannot cut corners.","bottom line|lo esencial / resultado final|The bottom line is cost.","play it by ear|improvisar|Let us play it by ear.","get the ball rolling|poner en marcha|Let us get the ball rolling.","on the same page|de acuerdo|Are we on the same page?"],
 dial:{t:"A project stand-up", l:[
  "A|Where are we with the Lisbon proposal?|¿Cómo vamos con la propuesta de Lisboa?",
  "B|Slightly behind schedule, but nothing critical.|Con algo de retraso, pero nada crítico.",
  "A|What is holding it up?|¿Qué lo está frenando?",
  "B|We are waiting on legal. That is not my call.|Estamos a la espera de jurídico. Eso no depende de mí.",
  "A|Can we get the ball rolling on the design meanwhile?|¿Podemos ir arrancando con el diseño mientras tanto?",
  "B|We could, as long as we do not cut corners.|Podríamos, siempre que no hagamos chapuzas.",
  "A|Agreed. The bottom line is the deadline.|De acuerdo. Lo esencial es el plazo.",
  "B|Let us touch base on Thursday.|Hablamos el jueves.",
  "A|And the budget issue?|¿Y el tema del presupuesto?",
  "B|Let us take that one offline.|Eso lo tratamos aparte."]},
 esc:[{q:"What is delaying the proposal?",o:["Design","Legal","Budget"],k:1},
      {q:"What matters most?",o:["The deadline","The design","The client"],k:0},
      {q:"When will they speak again?",o:["Monday","Thursday","Never"],k:1}],
 gram:{t:"Colocaciones y modismos profesionales", idea:"El B2 se reconoce por las <b>colocaciones</b>: <i>meet a deadline, reach an agreement, raise an issue, take responsibility, make a decision, do research, run a business, hold a meeting</i>. Los modismos de oficina (<i>touch base, in the pipeline, play it by ear</i>) son frecuentísimos en reuniones reales.",
  ej:["We need to meet the deadline.","They reached an agreement.","She raised an important issue.","Let us touch base next week.","We have two projects in the pipeline.","Are we all on the same page?"],
  nota:"Las colocaciones no se deducen: <i>make a decision</i> pero <i>take a decision</i> (británico), <i>do research</i> nunca <i>make research</i>, <i>meet a deadline</i> nunca <i>accomplish a deadline</i>.",
  drill:[["We must ___ the deadline.","meet"],["They ___ an agreement.","reached"],["Let us ___ base next week.","touch"],["Two projects are in the ___ .","pipeline"]]},
 prod:{habla:"Dirige una reunión imaginaria de cinco minutos usando ocho colocaciones o modismos profesionales.",
  escribe:"Escribe el resumen de una reunión en 6 frases.",
  modelo:"The Lisbon proposal is slightly behind schedule, mainly because we are waiting on the legal department. That decision is not ours to make, so there is no point in raising it again this week. In the meantime we can get the ball rolling on the design, provided we do not cut corners. The bottom line is that the client expects delivery on the fifteenth. We have two further projects in the pipeline that depend on this one. I will touch base with the team on Thursday to make sure we are all on the same page.",
  tr:["Tenemos que cumplir el plazo.","We have to meet the deadline."]},
 test:[
  {q:"We must ___ the deadline.",o:["accomplish","meet","reach to","arrive"],k:1},
  {q:"They ___ an agreement.",o:["arrived","reached","took","did"],k:1},
  {q:"'Touch base' significa…",o:["tocar fondo","ponerse en contacto","empezar de cero","tocar base física"],k:1},
  {q:"'In the pipeline' significa…",o:["en la tubería","en preparación","atascado","en la lista negra"],k:1},
  {q:"'Cut corners' significa…",o:["ahorrar tiempo bien","hacer chapuzas por ahorrar","cortar esquinas físicas","recortar plantilla"],k:1},
  {q:"'That is not my call' significa…",o:["No es mi llamada","No es decisión mía","No me llaman","No es mi turno"],k:1},
  {q:"Elige la colocación correcta:",o:["make research","do research","take research","have research"],k:1},
  {q:"'On the same page' significa…",o:["en la misma página","de acuerdo","al día","en el mismo sitio"],k:1}]
},
{
 d:14, tema:"REPASO · Presentación oral", objetivo:"Estructurar y sostener una presentación de cinco minutos.",
 chunks:["I would like to begin by outlining the context.","Moving on to my second point…","As you can see from the figures…","This brings me to my main conclusion.","To sum up, three things matter.","I am happy to take any questions."],
 vocab:["outline|esbozar|Let me outline the plan.","highlight|destacar|I would like to highlight this.","move on to|pasar a|Moving on to the next point.","bring me to|llevarme a|That brings me to my conclusion.","sum up|resumir|To sum up, three points.","take questions|responder preguntas|I will take questions now.","bear in mind|tener en cuenta|Bear in mind the cost.","in a nutshell|en pocas palabras|In a nutshell, it works.","the key takeaway|la idea clave|The key takeaway is simple.","back up|respaldar|The data back this up."],
 dial:{t:"Opening and closing a presentation", l:[
  "A|Good morning. I would like to begin by outlining the context.|Buenos días. Me gustaría empezar esbozando el contexto.",
  "B|How long will the presentation take?|¿Cuánto durará la presentación?",
  "A|About ten minutes, and then I will take questions.|Unos diez minutos, y después responderé preguntas.",
  "A|As you can see from the figures, demand has fallen.|Como pueden ver en las cifras, la demanda ha caído.",
  "B|Is that trend confirmed?|¿Está confirmada esa tendencia?",
  "A|The data back it up, although with some caveats.|Los datos lo respaldan, aunque con matices.",
  "A|Moving on to my second point: costs.|Paso a mi segundo punto: los costes.",
  "B|Bear in mind that energy prices have doubled.|Tenga en cuenta que la energía se ha duplicado.",
  "A|Precisely. Which brings me to my conclusion.|Precisamente. Lo cual me lleva a mi conclusión.",
  "A|To sum up: cut costs, delay the launch, keep the team.|En resumen: recortar costes, retrasar el lanzamiento y mantener el equipo."]},
 esc:[{q:"How long is the presentation?",o:["Five minutes","About ten minutes","Half an hour"],k:1},
      {q:"What has happened to demand?",o:["It has fallen","It has risen","It is stable"],k:0},
      {q:"What are the three conclusions?",o:["Cut costs, delay launch, keep the team","Hire, invest, expand","Sell, close, move"],k:0}],
 gram:{t:"Estructura del discurso", idea:"Apertura: <i>I would like to begin by… / My aim today is to…</i> Transición: <i>Moving on to… / Turning to… / That brings me to…</i> Apoyo visual: <i>As you can see from… / This chart shows…</i> Cierre: <i>To sum up… / In conclusion… / The key takeaway is…</i> Preguntas: <i>I am happy to take any questions.</i>",
  ej:["I would like to begin by outlining the context.","Moving on to my second point…","As you can see from the figures…","That brings me to my conclusion.","To sum up, three things matter.","I am happy to take any questions."],
  nota:"En inglés se anuncia siempre la estructura al principio (<i>I will cover three points</i>). El oyente anglosajón espera ese mapa; sin él, percibe desorden.",
  drill:[["I would like to begin ___ outlining the context.","by"],["___ on to my second point.","Moving"],["That ___ me to my conclusion.","brings"],["To ___ up, three things matter.","sum"]]},
 prod:{habla:"Da una presentación real de cinco minutos sobre tu trabajo con introducción, tres puntos y conclusión.",
  escribe:"Escribe el guion de una presentación de 8 frases.",
  modelo:"Good morning, and thank you for coming. I would like to begin by outlining the context, and then I will cover three points: demand, costs and timing. As you can see from the first chart, demand has fallen by twelve per cent since January. The data back this up, although there are some regional caveats worth mentioning. Moving on to my second point, energy prices have almost doubled in the same period. Bear in mind that this affects our two main suppliers directly. That brings me to my conclusion: we should delay the launch by one quarter. To sum up, cut costs, postpone the launch and keep the team together. I am happy to take any questions.",
  tr:["En resumen, tres cosas importan.","To sum up, three things matter."]},
 test:[
  {q:"I would like to begin ___ outlining the context.",o:["for","by","with to","to"],k:1},
  {q:"___ on to my second point.",o:["Move","Moving","Moved","To move"],k:1},
  {q:"That ___ me to my conclusion.",o:["takes","brings","carries","gets"],k:1},
  {q:"To ___ up, three things matter.",o:["sum","summarise it","resume","add"],k:0},
  {q:"'Bear in mind' significa…",o:["soportar en la mente","tener en cuenta","aguantar","recordar de memoria"],k:1},
  {q:"'The key takeaway' significa…",o:["la comida para llevar","la idea clave","la llave","la conclusión secundaria"],k:1},
  {q:"'The data back this up' significa…",o:["Los datos lo respaldan","Los datos retroceden","Los datos suben","Los datos lo desmienten"],k:0},
  {q:"'In a nutshell' significa…",o:["en una cáscara","en pocas palabras","en un aprieto","en detalle"],k:1}]
},
{
 d:15, tema:"Phrasal verbs de nivel alto", objetivo:"Entender el inglés real, que va lleno de ellos.",
 chunks:["The meeting dragged on for hours.","We need to iron out a few details.","She talked me out of it.","It all boils down to money.","They are cutting back on staff.","I cannot get my head round it."],
 vocab:["drag on|alargarse|The meeting dragged on.","iron out|limar (detalles)|Iron out the details.","talk out of|disuadir de|She talked me out of it.","boil down to|reducirse a|It boils down to money.","cut back on|recortar|Cutting back on costs.","get your head round|hacerse a la idea|I cannot get my head round it.","fall through|irse al traste|The deal fell through.","stand in for|sustituir a|I stood in for her.","put up with|aguantar|I will not put up with it.","come up with|idear|He came up with a plan."],
 dial:{t:"After a failed deal", l:[
  "A|So the Lisbon deal fell through?|¿Así que lo de Lisboa se fue al traste?",
  "B|Completely. It all boiled down to the price.|Del todo. Todo se redujo al precio.",
  "A|Could you not iron out the differences?|¿No pudisteis limar las diferencias?",
  "B|We tried. The negotiation dragged on for six weeks.|Lo intentamos. La negociación se alargó seis semanas.",
  "A|Who was standing in for the director?|¿Quién sustituía al director?",
  "B|I was, which did not help.|Yo, lo cual no ayudó.",
  "A|Did anyone come up with an alternative?|¿Alguien propuso una alternativa?",
  "B|Marta did, but they talked her out of it.|Marta sí, pero la disuadieron.",
  "A|I cannot get my head round that decision.|No consigo hacerme a la idea de esa decisión.",
  "B|Neither can I. Now we are cutting back on everything.|Yo tampoco. Ahora estamos recortando en todo."]},
 esc:[{q:"Why did the deal fail?",o:["The price","The timing","The location"],k:0},
      {q:"How long did the negotiation last?",o:["Six days","Six weeks","Six months"],k:1},
      {q:"What is happening now?",o:["Hiring","Cutting back on everything","Expanding"],k:1}],
 gram:{t:"Phrasal verbs de tres partes y registro", idea:"Los de tres partes son inseparables y muy frecuentes: <i>get on with, put up with, look forward to, come up with, cut back on, get out of, catch up on, run out of, look down on, stand up for</i>. En registro formal se sustituyen por su equivalente latino: <i>cut back on → reduce</i>, <i>come up with → propose</i>, <i>find out → discover</i>.",
  ej:["The meeting dragged on for hours.","We need to iron out a few details.","It all boils down to money.","They are cutting back on staff.","He came up with a plan.","I cannot get my head round it."],
  nota:"Regla de registro: en un informe escrito usa el verbo latino; en una reunión hablada, el phrasal. Mezclarlos al revés suena raro en ambos sentidos.",
  drill:[["The meeting dragged ___ for hours.","on"],["We need to iron ___ the details.","out"],["It all boils ___ to money.","down"],["They are cutting ___ on staff.","back"]]},
 prod:{habla:"Cuenta un proyecto fallido usando diez phrasal verbs avanzados.",
  escribe:"Escribe 6 frases con phrasal verbs de nivel alto.",
  modelo:"The Lisbon deal finally fell through last Friday after six weeks of talks. The negotiation dragged on far longer than anyone had expected. In the end it all boiled down to a difference of eight per cent on the price. We tried to iron out the details, but their lawyers kept raising new objections. Marta came up with a sensible alternative, although the board talked her out of presenting it. Now the company is cutting back on everything, and I still cannot get my head round how badly it was handled.",
  tr:["Todo se reduce al dinero.","It all boils down to money."]},
 test:[
  {q:"The meeting dragged ___ for hours.",o:["on","out","up","over"],k:0},
  {q:"We need to iron ___ the details.",o:["on","out","up","over"],k:1},
  {q:"It all boils ___ to money.",o:["up","down","over","off"],k:1},
  {q:"'Fall through' significa…",o:["caerse dentro","irse al traste","atravesar","fracasar por poco"],k:1},
  {q:"'Come up with' significa…",o:["subir con","idear / proponer","aparecer","acompañar"],k:1},
  {q:"'Stand in for' significa…",o:["defender","sustituir a","estar dentro","aguantar"],k:1},
  {q:"'Cut back on' en registro formal es…",o:["increase","reduce","remove","postpone"],k:1},
  {q:"'Talk somebody out of something' significa…",o:["convencer de hacerlo","disuadir de hacerlo","hablar fuera","contarlo"],k:1}]
},
{
 d:16, tema:"Subrayar lo que dices", objetivo:"Enfatizar con recursos gramaticales y léxicos.",
 chunks:["I do understand your concern.","It was absolutely essential.","That is exactly what I meant.","She herself admitted it.","Never in my life have I been so surprised.","It is by far the best option."],
 vocab:["do + verb|sí que (énfasis)|I do agree.","absolutely|absolutamente|Absolutely right.","utterly|completamente|Utterly wrong.","by far|con diferencia|By far the best.","in the slightest|en absoluto|Not in the slightest.","whatsoever|en absoluto|No doubt whatsoever.","precisely|precisamente|Precisely my point.","indeed|efectivamente|It is indeed true.","far from|lejos de|Far from easy.","anything but|todo menos|Anything but simple."],
 dial:{t:"Defending a position firmly", l:[
  "A|You do not seem convinced.|No pareces convencido.",
  "B|I do understand the logic. I simply disagree.|Sí que entiendo la lógica. Sencillamente no estoy de acuerdo.",
  "A|Is the plan really that risky?|¿Tan arriesgado es el plan?",
  "B|It is anything but safe.|Es todo menos seguro.",
  "A|That is a strong statement.|Es una afirmación fuerte.",
  "B|It is precisely what the data show.|Es precisamente lo que muestran los datos.",
  "A|Does the board share your view?|¿El consejo comparte tu opinión?",
  "B|The chairman himself raised the same concern.|El propio presidente planteó la misma preocupación.",
  "A|So there is no support at all?|¿Así que no hay ningún apoyo?",
  "B|None whatsoever. And it is by far the costliest option.|Ninguno en absoluto. Y es con diferencia la opción más cara."]},
 esc:[{q:"Does B understand the logic?",o:["No","Yes, but disagrees","Partly"],k:1},
      {q:"Who raised the same concern?",o:["The chairman himself","Nobody","The client"],k:0},
      {q:"How much support is there?",o:["A lot","None whatsoever","Some"],k:1}],
 gram:{t:"Recursos de énfasis", idea:"<b>do/does/did + infinitivo</b> para reforzar una afirmación (<i>I do understand</i>). <b>Pronombres reflexivos</b> enfáticos (<i>She herself admitted it</i>). <b>Adverbios intensificadores</b> (<i>absolutely, utterly, by far, precisely</i>). <b>Negación reforzada</b> (<i>none whatsoever, not in the slightest</i>). <b>Anything but / far from</b> = todo menos.",
  ej:["I do understand your concern.","She herself admitted it.","It is absolutely essential.","It is by far the best option.","There is no doubt whatsoever.","It is anything but simple."],
  nota:"Los intensificadores tienen pareja fija: <i>absolutely essential</i> (adjetivos extremos) frente a <i>very important</i> (adjetivos graduables). No se dice <i>very essential</i> ni <i>absolutely important</i>.",
  drill:[["I ___ understand your concern. (énfasis)","do"],["She ___ admitted it.","herself"],["It is ___ far the best option.","by"],["There is no doubt ___ .","whatsoever"]]},
 prod:{habla:"Defiende con firmeza una postura impopular usando seis recursos de énfasis.",
  escribe:"Escribe 6 frases enfáticas.",
  modelo:"I do understand why the board finds the proposal attractive, but I simply do not share the enthusiasm. The plan is anything but low-risk, and the figures make that absolutely clear. It is by far the most expensive of the three options on the table. The chairman himself raised exactly the same concern at the last meeting. There is no financial justification whatsoever for committing now rather than in September. Far from being cautious, waiting one quarter is the only responsible decision.",
  tr:["Sí que entiendo tu preocupación.","I do understand your concern."]},
 test:[
  {q:"I ___ understand your concern.",o:["do","am","have","very"],k:0},
  {q:"She ___ admitted it.",o:["self","herself","her own","same"],k:1},
  {q:"It is ___ the best option.",o:["for far","by far","far by","very far"],k:1},
  {q:"There is no doubt ___ .",o:["at all whatever","whatsoever","whatever so","in all"],k:1},
  {q:"Elige la correcta:",o:["very essential","absolutely essential","absolutely important only","very perfect"],k:1},
  {q:"'Anything but simple' significa…",o:["cualquier cosa simple","todo menos simple","algo simple","casi simple"],k:1},
  {q:"'Not in the slightest' significa…",o:["en absoluto","levemente","no del todo","ligeramente sí"],k:0},
  {q:"'Indeed' sirve para…",o:["negar","confirmar con énfasis","preguntar","dudar"],k:1}]
},
{
 d:17, tema:"Marcadores del habla real", objetivo:"Sonar natural con los conectores de la conversación.",
 chunks:["Mind you, it was not easy.","Having said that, I would try again.","As it happens, I was there.","To be fair, he did warn us.","Come to think of it, that explains everything.","Anyway, where were we?"],
 vocab:["mind you|eso sí|Mind you, it was cheap.","having said that|dicho esto|Having said that, I agree.","as it happens|da la casualidad|As it happens, I know him.","come to think of it|ahora que lo pienso|Come to think of it, yes.","by the way|por cierto|By the way, she called.","anyway|en fin|Anyway, let us continue.","actually|en realidad|Actually, it was Tuesday.","I mean|quiero decir|I mean, it is obvious.","sort of|más o menos|It is sort of complicated.","you know|ya sabes|It is difficult, you know."],
 dial:{t:"A relaxed conversation about a trip", l:[
  "A|So how was the trip? Worth it?|¿Y qué tal el viaje? ¿Mereció la pena?",
  "B|Sort of. Mind you, the weather was terrible.|Más o menos. Eso sí, el tiempo fue horrible.",
  "A|That is bad luck.|Qué mala suerte.",
  "B|Having said that, the museums were extraordinary.|Dicho esto, los museos fueron extraordinarios.",
  "A|Did you see the exhibition everyone talks about?|¿Viste la exposición de la que todos hablan?",
  "B|As it happens, I got the last ticket.|Da la casualidad de que pillé la última entrada.",
  "A|Lucky. Was the hotel any good?|Qué suerte. ¿El hotel estaba bien?",
  "B|Awful. To be fair, it was very cheap.|Horrible. Para ser justos, era muy barato.",
  "A|You do get what you pay for.|Ya se sabe, lo barato sale caro.",
  "B|Come to think of it, that is the lesson of the whole trip.|Ahora que lo pienso, esa es la lección de todo el viaje."]},
 esc:[{q:"How was the weather?",o:["Terrible","Perfect","Changeable"],k:0},
      {q:"Did B see the exhibition?",o:["No","Yes, with the last ticket","It was closed"],k:1},
      {q:"What was wrong with the hotel?",o:["It was awful but cheap","Too expensive","Too far"],k:0}],
 gram:{t:"Marcadores del discurso hablado", idea:"Organizan la conversación y suavizan: <b>Mind you</b> (matiz contrario), <b>Having said that</b> (concesión), <b>As it happens</b> (coincidencia), <b>To be fair</b> (justicia), <b>Come to think of it</b> (idea repentina), <b>Anyway</b> (retomar), <b>Actually</b> (corregir con suavidad), <b>I mean</b> (reformular).",
  ej:["Mind you, it was not easy.","Having said that, I would try again.","As it happens, I was there.","To be fair, he did warn us.","Anyway, where were we?","Actually, it was on Tuesday."],
  nota:"<i>Actually</i> es un falso amigo peligroso: significa <b>en realidad</b>, no <i>actualmente</i> (que sería <i>currently / at present</i>).",
  drill:[["___ you, it was not easy.","Mind"],["___ said that, I would try again.","Having"],["As it ___ , I was there.","happens"],["___ to think of it, that explains it.","Come"]]},
 prod:{habla:"Mantén una conversación informal de dos minutos usando ocho marcadores del habla.",
  escribe:"Escribe un relato coloquial de 6 frases con marcadores.",
  modelo:"The trip was good, sort of. Mind you, it rained every single day and we barely left the hotel in the afternoons. Having said that, the museums were genuinely extraordinary and worth the whole journey. As it happens, I managed to get the last ticket for the exhibition everyone is talking about. The hotel was awful, although to be fair it cost almost nothing. Come to think of it, that is probably the lesson of the entire holiday.",
  tr:["Eso sí, no fue fácil.","Mind you, it was not easy."]},
 test:[
  {q:"___ you, it was not easy.",o:["Mind","Minding","Mine","Remind"],k:0},
  {q:"___ said that, I would try again.",o:["Have","Having","Had","To have"],k:1},
  {q:"'As it happens' significa…",o:["mientras pasa","da la casualidad de que","según ocurre","como pasa siempre"],k:1},
  {q:"'Actually' significa…",o:["actualmente","en realidad","de hecho ahora","activamente"],k:1},
  {q:"'Come to think of it' significa…",o:["ven a pensarlo","ahora que lo pienso","piénsalo","pensándolo mal"],k:1},
  {q:"'To be fair' introduce…",o:["una crítica","una matización justa","una queja","una orden"],k:1},
  {q:"'Anyway' sirve para…",o:["negar","retomar o cerrar el tema","insistir","dudar"],k:1},
  {q:"'Sort of' significa…",o:["ordenado","más o menos","clasificado","de tipo"],k:1}]
},
{
 d:18, tema:"Cambiar de registro", objetivo:"Reescribir el mismo contenido en formal e informal.",
 chunks:["We regret to inform you that your application was unsuccessful.","Sorry, you did not get the job.","Please do not hesitate to contact me.","Just give me a shout.","The matter requires further consideration.","We need to think about it a bit more."],
 vocab:["regret to inform|lamentar informar|We regret to inform you.","unsuccessful|no seleccionado|Your application was unsuccessful.","do not hesitate|no dude en|Do not hesitate to call.","give a shout|avisar|Give me a shout.","further|adicional|Further information.","require|requerir|It requires attention.","obtain|obtener|To obtain a permit.","purchase|adquirir|To purchase tickets.","commence|comenzar|Work will commence in May.","terminate|finalizar|The contract terminates in June."],
 dial:{t:"The same news, two ways", l:[
  "A|We regret to inform you that your application was unsuccessful.|Lamentamos informarle de que su solicitud no ha sido seleccionada.",
  "B|Sorry mate, you did not get it.|Lo siento, tío, no te lo han dado.",
  "A|The selection panel received an exceptional number of applications.|El tribunal recibió un número excepcional de solicitudes.",
  "B|Loads of people applied.|Se presentó muchísima gente.",
  "A|Your profile will be retained for future vacancies.|Guardaremos su perfil para futuras vacantes.",
  "B|We will keep you in mind.|Te tendremos en cuenta.",
  "A|Should you require feedback, please do not hesitate to contact us.|Si desea comentarios, no dude en contactarnos.",
  "B|If you want to know why, just give me a shout.|Si quieres saber por qué, avísame.",
  "A|We wish you every success in your future endeavours.|Le deseamos mucho éxito en sus futuros proyectos.",
  "B|Good luck with everything!|¡Suerte con todo!"]},
 esc:[{q:"What is the news?",o:["The application failed","The job is offered","An interview is scheduled"],k:0},
      {q:"What happens to the profile?",o:["It is deleted","It is kept for future vacancies","It is published"],k:1},
      {q:"What is offered at the end?",o:["Feedback on request","Money","Another interview"],k:0}],
 gram:{t:"Registro: formal frente a informal", idea:"El formal prefiere <b>verbos de origen latino</b> (<i>obtain, purchase, commence, require, terminate, assist</i>), evita contracciones y phrasal verbs, usa <b>pasivas</b> e <b>impersonales</b>, y fórmulas fijas (<i>Should you require…, We regret to inform you…</i>). El informal usa phrasal verbs, contracciones y frases cortas.",
  ej:["We regret to inform you… / Sorry, but…","Please do not hesitate to contact me. / Just give me a shout.","The matter requires consideration. / We need to think about it.","Work will commence in May. / We start in May.","Should you require assistance… / If you need help…","The contract terminates in June. / It ends in June."],
  nota:"<i>Should you require…</i> es una inversión condicional formal: equivale a <i>If you require…</i> Se usa muchísimo en correspondencia comercial.",
  drill:[["Formal de 'we need': we ___","require"],["Formal de 'buy': ___","purchase"],["Formal de 'start': ___","commence"],["___ you require assistance, contact us.","Should"]]},
 prod:{habla:"Da la misma mala noticia dos veces en voz alta: primero a un cliente formal y luego a un amigo.",
  escribe:"Escribe un mensaje formal (5 frases) y su versión informal (5 frases).",
  modelo:"FORMAL: Dear Ms Blanco, We regret to inform you that your application for the position of project architect has been unsuccessful on this occasion. The selection panel received an exceptional number of applications of a very high standard. Your details will be retained for a period of twelve months in case a suitable vacancy arises. Should you require individual feedback, please do not hesitate to contact this office. We wish you every success in your future endeavours. — INFORMAL: Hi Ana, sorry, you did not get it this time. Loads of really strong people applied. We will keep your CV in case something comes up. If you want to know why, just give me a shout. Good luck with everything!",
  tr:["No dude en ponerse en contacto conmigo.","Please do not hesitate to contact me."]},
 test:[
  {q:"Formal de 'buy':",o:["get","purchase","take","pick up"],k:1},
  {q:"Formal de 'start':",o:["kick off","commence","get going","begin to"],k:1},
  {q:"___ you require assistance, contact us.",o:["If","Should","Would","Had"],k:1},
  {q:"'Do not hesitate to contact me' es…",o:["informal","formal","neutro coloquial","agresivo"],k:1},
  {q:"¿Cuál es informal?",o:["We regret to inform you.","Give me a shout.","The matter requires consideration.","Work will commence in May."],k:1},
  {q:"'Unsuccessful application' significa…",o:["solicitud no seleccionada","solicitud incompleta","solicitud tardía","solicitud repetida"],k:0},
  {q:"En registro formal se evitan…",o:["las pasivas","las contracciones","los tecnicismos","las fórmulas fijas"],k:1},
  {q:"'Terminate' significa…",o:["terminar / rescindir","exterminar","determinar","finalizar mal"],k:0}]
},
{
 d:19, tema:"Especular a fondo", objetivo:"Analizar causas y consecuencias con matices de probabilidad.",
 chunks:["There is every chance that it will work.","It is highly unlikely that they knew.","The odds are against us.","Chances are he simply forgot.","I would not rule it out.","It stands to reason that costs will rise."],
 vocab:["every chance|muchas posibilidades|There is every chance.","highly unlikely|muy improbable|Highly unlikely.","the odds|las probabilidades|The odds are low.","rule out|descartar|I would not rule it out.","stands to reason|es lógico|It stands to reason.","conceivably|posiblemente|Conceivably, yes.","far-fetched|inverosímil|That sounds far-fetched.","plausible|verosímil|A plausible explanation.","account for|explicar|That accounts for the delay.","put down to|atribuir a|I put it down to stress."],
 dial:{t:"Analysing a failure", l:[
  "A|What accounts for the drop in sales?|¿A qué se debe la caída de ventas?",
  "B|Chances are it is simply the price increase.|Lo más probable es que sea sencillamente la subida de precios.",
  "A|Could the new packaging be responsible?|¿Podría ser culpa del nuevo envase?",
  "B|Conceivably, but it seems far-fetched.|Posiblemente, pero parece inverosímil.",
  "A|Would you rule out the competition?|¿Descartarías a la competencia?",
  "B|I would not rule it out entirely.|No lo descartaría del todo.",
  "A|Is it likely that the campaign failed?|¿Es probable que la campaña fracasara?",
  "B|Highly unlikely. The metrics were excellent.|Muy improbable. Las métricas fueron excelentes.",
  "A|So it stands to reason that price is the factor.|Entonces es lógico que el factor sea el precio.",
  "B|The odds are strongly in favour of that explanation.|Las probabilidades apuntan claramente a esa explicación."]},
 esc:[{q:"What is the most likely cause?",o:["The packaging","The price increase","The campaign"],k:1},
      {q:"How does B rate the packaging theory?",o:["Certain","Far-fetched","Proven"],k:1},
      {q:"Was the campaign a failure?",o:["Highly unlikely","Certainly","Probably"],k:0}],
 gram:{t:"Grados de probabilidad", idea:"Escala: <i>It is certain / bound to happen</i> → <i>There is every chance / Chances are</i> → <i>It is likely / probable</i> → <i>It may well</i> → <i>It is possible / conceivably</i> → <i>It is unlikely</i> → <i>It is highly unlikely</i> → <i>There is no chance</i>. Construcciones: <b>It is likely that + frase</b> o <b>be likely to + infinitivo</b>.",
  ej:["There is every chance that it will work.","Chances are he simply forgot.","It is likely to rain.","It may well be the price.","It is highly unlikely that they knew.","I would not rule it out."],
  nota:"<i>It stands to reason that…</i> = es de cajón. <i>To put something down to something</i> = atribuirlo a. Son dos fórmulas muy rentables en análisis.",
  drill:[["There is every ___ that it will work.","chance"],["___ are he simply forgot.","Chances"],["It is highly ___ that they knew.","unlikely"],["I would not ___ it out.","rule"]]},
 prod:{habla:"Analiza en voz alta las causas posibles de un problema real graduando cinco niveles de probabilidad.",
  escribe:"Escribe 6 frases especulando sobre las causas de un problema.",
  modelo:"Chances are that the drop in sales is simply a reaction to the price increase in February. It is highly unlikely that the campaign is to blame, since every metric was above target. Conceivably the new packaging has confused regular customers, although that explanation seems slightly far-fetched. I would not rule out pressure from the two competitors who launched in March. It stands to reason that a fifteen per cent rise would affect volume in this segment. On balance, I would put the whole thing down to price rather than marketing.",
  tr:["Es muy improbable que lo supieran.","It is highly unlikely that they knew."]},
 test:[
  {q:"There is every ___ that it will work.",o:["chance","possible","odd","likely"],k:0},
  {q:"___ are he simply forgot.",o:["Chance","Chances","Odds is","Probable"],k:1},
  {q:"It is highly ___ that they knew.",o:["unlike","unlikely","dislikely","not likely to"],k:1},
  {q:"I would not ___ it out.",o:["rule","role","roll","rub"],k:0},
  {q:"'It stands to reason' significa…",o:["se sostiene razonando","es lógico / es de cajón","tiene razón","hay que razonarlo"],k:1},
  {q:"'Far-fetched' significa…",o:["traído de lejos, inverosímil","muy buscado","alejado","futuro"],k:0},
  {q:"'Put it down to stress' significa…",o:["dejarlo por estrés","atribuirlo al estrés","apuntarlo","reducirlo"],k:1},
  {q:"It is likely ___ rain.",o:["that","to","for","of"],k:1,exp:"be likely to + infinitivo"}]
},
{
 d:20, tema:"Conceder y rebatir", objetivo:"Construir contraargumentos elegantes.",
 chunks:["Granted, the cost is high.","Whilst I accept the principle, the timing is wrong.","That may be so, but the evidence says otherwise.","There is some truth in that.","Even if that were true, it would not change anything.","The counter-argument is straightforward."],
 vocab:["granted|concedido|Granted, it is expensive.","whilst|si bien|Whilst I agree, I hesitate.","that may be so|puede que sea así|That may be so, but…","there is some truth in|hay algo de verdad en|There is some truth in that.","even if|incluso si|Even if that were true.","counter-argument|contraargumento|The counter-argument is clear.","overstate|exagerar|You overstate the risk.","concede|conceder|I concede the point.","flawed|defectuoso|A flawed argument.","beside the point|irrelevante|That is beside the point."],
 dial:{t:"A disagreement between colleagues", l:[
  "A|The investment is simply too expensive.|La inversión es sencillamente demasiado cara.",
  "B|Granted, the initial cost is high.|Concedido, el coste inicial es alto.",
  "A|So you agree with me.|Entonces estás de acuerdo conmigo.",
  "B|Whilst I accept the figure, I question the conclusion.|Si bien acepto la cifra, cuestiono la conclusión.",
  "A|The money has to come from somewhere.|El dinero tiene que salir de algún sitio.",
  "B|That may be so, but you are overstating the risk.|Puede que sea así, pero estás exagerando el riesgo.",
  "A|The board thinks otherwise.|El consejo opina lo contrario.",
  "B|With respect, that is beside the point.|Con todo el respeto, eso es irrelevante.",
  "A|Even if the return is good, the timing is wrong.|Aunque el retorno sea bueno, el momento no es el adecuado.",
  "B|There is some truth in that, I concede.|Hay algo de verdad en eso, lo concedo."]},
 esc:[{q:"What does B concede?",o:["The initial cost is high","The plan is bad","The timing is wrong"],k:0},
      {q:"What does B accuse A of?",o:["Lying","Overstating the risk","Being late"],k:1},
      {q:"What does B finally accept?",o:["Nothing","Some truth in the timing argument","The whole argument"],k:1}],
 gram:{t:"Concesión y refutación", idea:"Conceder: <b>Granted / Admittedly / It is true that / I concede that / There is some truth in that</b>. Refutar: <b>That may be so, but… / Nevertheless / However / That said / The problem with that argument is…</b>. Hipótesis concesiva: <b>Even if + past subjunctive</b> (<i>Even if that were true…</i>).",
  ej:["Granted, the cost is high.","Whilst I accept the principle, the timing is wrong.","That may be so, but the evidence says otherwise.","Even if that were true, it would change nothing.","There is some truth in that.","That is beside the point."],
  nota:"Fórmula de oro del debate B2: <b>concesión + pero + evidencia</b>. Quien solo niega parece rígido; quien concede y rebate parece que domina el tema.",
  drill:[["___ , the cost is high. (concedido)","Granted"],["That ___ be so, but the evidence differs.","may"],["Even if that ___ true, it would change nothing.","were"],["There is some ___ in that.","truth"]]},
 prod:{habla:"Rebate durante dos minutos una postura contraria concediendo primero dos puntos válidos.",
  escribe:"Escribe un contraargumento de 6 frases.",
  modelo:"Granted, the initial investment is considerably higher than we planned in January. Whilst I accept that figure, I would question the conclusion that is being drawn from it. That may be so, but the analysis appears to overstate the risk of a downturn. Even if the worst-case scenario were true, we would still recover the cost within four years. There is some truth in the argument about timing, and I concede that point willingly. The objection about the board's preferences, however, is beside the point entirely.",
  tr:["Concedido, el coste es alto.","Granted, the cost is high."]},
 test:[
  {q:"___ , the cost is high.",o:["Granted","Granting","Grant","To grant"],k:0},
  {q:"That ___ be so, but the evidence differs.",o:["can","may","must","should"],k:1},
  {q:"Even if that ___ true, it would change nothing.",o:["is","was","were","would be"],k:2},
  {q:"'Beside the point' significa…",o:["junto al punto","irrelevante","casi correcto","fuera de plazo"],k:1},
  {q:"'I concede the point' significa…",o:["Concedo ese punto","Concedo el permiso","Gano el punto","Discuto el punto"],k:0},
  {q:"'Whilst' es…",o:["informal americano","formal británico = while","incorrecto","un sustantivo"],k:1},
  {q:"'Overstate' significa…",o:["exagerar","declarar de más","subestimar","sobreestimar el coste solo"],k:0},
  {q:"'A flawed argument' es un argumento…",o:["excelente","defectuoso","largo","famoso"],k:1}]
}
,
{
 d:21, tema:"REPASO · Ensayo de opinión", objetivo:"Escribir un texto argumentativo de nivel B2.",
 chunks:["It is often argued that…","There are compelling reasons to believe otherwise.","This essay will argue that…","A further consideration is…","In conclusion, the evidence points in one direction.","The issue is more nuanced than it appears."],
 vocab:["it is often argued|se suele argumentar|It is often argued that…","compelling|convincente|A compelling reason.","nuanced|matizado|A nuanced view.","a further consideration|otra consideración|A further consideration is cost.","the former / the latter|el primero / el segundo|The latter is preferable.","overall|en general|Overall, it works.","address|abordar|We must address the issue.","stem from|derivarse de|Problems stem from funding.","in essence|en esencia|In essence, it is simple.","ultimately|en última instancia|Ultimately, it is a choice."],
 dial:{t:"Planning an essay", l:[
  "A|What is the essay question?|¿Cuál es la pregunta del ensayo?",
  "B|Whether remote work damages young careers.|Si el teletrabajo perjudica las carreras jóvenes.",
  "A|What is your thesis?|¿Cuál es tu tesis?",
  "B|That the issue is more nuanced than it appears.|Que la cuestión es más matizada de lo que parece.",
  "A|How will you structure it?|¿Cómo lo estructurarás?",
  "B|Introduction, two arguments, one counter-argument, conclusion.|Introducción, dos argumentos, un contraargumento y conclusión.",
  "A|What is your strongest point?|¿Cuál es tu punto más fuerte?",
  "B|That mentoring stems from proximity, not policy.|Que la tutoría surge de la proximidad, no de la política de empresa.",
  "A|And the counter-argument?|¿Y el contraargumento?",
  "B|Flexibility retains talent. Ultimately, both are true.|La flexibilidad retiene talento. En última instancia, ambas son ciertas."]},
 esc:[{q:"What is the essay about?",o:["Remote work and young careers","Office design","Salaries"],k:0},
      {q:"What is the structure?",o:["Intro, 2 arguments, counter, conclusion","Intro and conclusion","Five arguments"],k:0},
      {q:"What is the strongest point?",o:["Mentoring stems from proximity","Money matters most","Offices are cheaper"],k:0}],
 gram:{t:"Estructura del ensayo argumentativo", idea:"Cuatro partes: <b>introducción</b> (contexto + tesis), <b>cuerpo</b> (un argumento por párrafo con evidencia), <b>contraargumento</b> (concedido y refutado) y <b>conclusión</b> (síntesis, sin ideas nuevas). Léxico: <i>It is often argued that…, A further consideration is…, The former/the latter, Ultimately…</i>",
  ej:["It is often argued that remote work harms junior staff.","This essay will argue that the picture is more nuanced.","A further consideration is the cost of office space.","Whilst flexibility retains talent, proximity builds skill.","The latter argument is more convincing than the former.","In conclusion, the answer depends on the stage of a career."],
  nota:"En un ensayo académico se evitan las contracciones, el <i>I think</i> repetido y las preguntas retóricas. Se prefiere <i>It could be argued that…</i>",
  drill:[["It is often ___ that remote work harms juniors.","argued"],["A ___ consideration is the cost.","further"],["The ___ argument is more convincing. (el segundo)","latter"],["___ , the answer depends on the context.","Ultimately"]]},
 prod:{habla:"Expón oralmente el guion de un ensayo: tesis, dos argumentos, contraargumento y conclusión.",
  escribe:"Escribe un ensayo de opinión de 10 frases.",
  modelo:"It is often argued that remote work damages the careers of young professionals. This essay will argue that the picture is considerably more nuanced than that claim suggests. The first consideration is that most professional learning is informal: juniors acquire judgement by overhearing decisions, not by attending scheduled meetings. A further consideration is that mentoring stems from proximity rather than from company policy, and no software has yet replaced it. Whilst these arguments are compelling, the counter-argument deserves attention. Flexibility demonstrably retains talent, particularly among employees with caring responsibilities. Granted, a fully remote junior may progress more slowly in the first two years. That may be so, but the evidence suggests the gap closes once basic competence is established. Overall, the sensible conclusion is neither full attendance nor full remote work. Ultimately, the answer depends on the stage of the career rather than on the technology available.",
  tr:["La cuestión es más matizada de lo que parece.","The issue is more nuanced than it appears."]},
 test:[
  {q:"It is often ___ that remote work harms juniors.",o:["argue","argued","arguing","argues"],k:1},
  {q:"A ___ consideration is the cost.",o:["farther","further","furthest","far"],k:1},
  {q:"'The latter' significa…",o:["el primero","el segundo mencionado","el último de todos","el tardío"],k:1},
  {q:"'Compelling' significa…",o:["obligatorio","convincente","competitivo","completo"],k:1},
  {q:"'Nuanced' significa…",o:["nuevo","matizado","molesto","anunciado"],k:1},
  {q:"'Stem from' significa…",o:["derivarse de","detener","sellar","provenir de una planta"],k:0},
  {q:"En un ensayo formal se evita…",o:["la evidencia","las contracciones","la estructura","los conectores"],k:1},
  {q:"'Ultimately' significa…",o:["últimamente","en última instancia","finalmente por fin","de forma última"],k:1}]
},
{
 d:22, tema:"Medio ambiente", objetivo:"Debatir sobre sostenibilidad con léxico preciso.",
 chunks:["We need to cut carbon emissions drastically.","Renewable energy is now cheaper than coal.","The measures do not go far enough.","It is a question of political will.","Recycling alone will not solve it.","The impact is already visible."],
 vocab:["emissions|emisiones|Cut carbon emissions.","renewable|renovable|Renewable energy.","landfill|vertedero|It ends up in landfill.","waste|residuos / desperdiciar|Reduce food waste.","carbon footprint|huella de carbono|A large carbon footprint.","offset|compensar|Offset the emissions.","sustainable|sostenible|A sustainable model.","greenwashing|ecopostureo|That is pure greenwashing.","depletion|agotamiento|Resource depletion.","phase out|eliminar gradualmente|Phase out coal."],
 dial:{t:"Debating climate policy", l:[
  "A|Do you think the new measures go far enough?|¿Crees que las nuevas medidas van lo bastante lejos?",
  "B|Frankly, no. They barely touch emissions.|Francamente, no. Apenas tocan las emisiones.",
  "A|But renewables are growing fast.|Pero las renovables crecen rápido.",
  "B|They are, and they are now cheaper than coal.|Así es, y ya son más baratas que el carbón.",
  "A|So what is missing?|¿Entonces qué falta?",
  "B|Political will. And a plan to phase out gas.|Voluntad política. Y un plan para eliminar el gas.",
  "A|Companies say they are offsetting emissions.|Las empresas dicen que compensan sus emisiones.",
  "B|Much of that is greenwashing, to be honest.|Mucho de eso es ecopostureo, sinceramente.",
  "A|Is individual recycling pointless, then?|¿Entonces reciclar a nivel individual no sirve?",
  "B|Not pointless, but recycling alone will not solve it.|No es inútil, pero reciclar solo no lo va a resolver."]},
 esc:[{q:"What does B think of the measures?",o:["Sufficient","They do not go far enough","Too strict"],k:1},
      {q:"What is missing according to B?",o:["Political will","Money","Technology"],k:0},
      {q:"What does B say about offsetting?",o:["It is effective","Much of it is greenwashing","It is illegal"],k:1}],
 gram:{t:"Léxico abstracto y verbos de tendencia", idea:"Para describir datos y tendencias: <b>rise / fall / soar / plummet / level off / peak</b>, con adverbios <i>sharply, steadily, slightly, dramatically</i>. Sustantivos abstractos frecuentes: <i>impact, measure, target, incentive, commitment, resource</i>. Colocaciones: <i>cut emissions, meet a target, set a deadline, raise awareness</i>.",
  ej:["Emissions have fallen sharply since 2019.","Prices soared last winter.","The curve levelled off in March.","We must meet the 2030 target.","The measures do not go far enough.","We need to raise awareness."],
  nota:"<i>Do not go far enough</i> es la crítica estándar a cualquier política; <i>go too far</i> es la contraria. Dos expresiones que aparecen en todo debate.",
  drill:[["Emissions have fallen ___ since 2019.","sharply"],["We must ___ the 2030 target.","meet"],["The measures do not go ___ enough.","far"],["We need to ___ awareness.","raise"]]},
 prod:{habla:"Debate dos minutos: ¿es responsabilidad del individuo o del Estado reducir emisiones?",
  escribe:"Escribe 8 frases sobre sostenibilidad con léxico preciso.",
  modelo:"Global emissions must fall by roughly half this decade if the 2050 target is to be met. The measures announced last month are welcome, but they clearly do not go far enough. Renewable energy is now cheaper than coal in most markets, which removes the main economic objection. What is missing is political will and a credible plan to phase out gas heating. Many corporate commitments amount to little more than greenwashing, since offsetting rarely removes the carbon claimed. That is not an argument against individual action, but recycling alone will not solve a structural problem. Household waste is a fraction of industrial waste, and most plastic still ends up in landfill. Ultimately, the debate is about regulation rather than about personal virtue.",
  tr:["Las medidas no van lo bastante lejos.","The measures do not go far enough."]},
 test:[
  {q:"Emissions have fallen ___ since 2019.",o:["sharp","sharply","sharper","in sharp"],k:1},
  {q:"We must ___ the 2030 target.",o:["accomplish","meet","arrive","reach to"],k:1},
  {q:"'The measures do not go far enough' significa…",o:["No llegan lejos","Se quedan cortas","Son excesivas","No funcionan"],k:1},
  {q:"'Greenwashing' significa…",o:["lavado ecológico / ecopostureo","limpieza verde","reciclaje","lavado industrial"],k:0},
  {q:"'Phase out' significa…",o:["eliminar gradualmente","salir de fase","poner en fase","acelerar"],k:0},
  {q:"'Landfill' significa…",o:["relleno de tierra","vertedero","terreno","aterrizaje"],k:1},
  {q:"'Carbon footprint' significa…",o:["pisada de carbón","huella de carbono","marca de fábrica","emisión directa"],k:1},
  {q:"Prices ___ last winter. (subieron muchísimo)",o:["soared","levelled","plummeted","peaked out"],k:0}]
},
{
 d:23, tema:"Medios y desinformación", objetivo:"Analizar noticias con sentido crítico.",
 chunks:["The story was blown out of proportion.","The headline is misleading.","According to unnamed sources…","The report has been widely disputed.","It is worth checking the original source.","There is a clear bias in the coverage."],
 vocab:["misleading|engañoso|A misleading headline.","bias|sesgo|A clear political bias.","coverage|cobertura|The media coverage.","source|fuente|An unnamed source.","claim|afirmación|An unverified claim.","dispute|cuestionar|The figure is disputed.","blow out of proportion|exagerar|It was blown out of proportion.","outlet|medio|A major news outlet.","fact-check|verificar|We must fact-check it.","spin|manipular el enfoque|Political spin."],
 dial:{t:"Discussing a news story", l:[
  "A|Did you see the headline about the hospital?|¿Viste el titular sobre el hospital?",
  "B|I did. It is deeply misleading.|Sí. Es muy engañoso.",
  "A|In what sense?|¿En qué sentido?",
  "B|The figure comes from an unnamed source.|La cifra viene de una fuente sin identificar.",
  "A|Has anyone checked it?|¿Alguien lo ha verificado?",
  "B|Two outlets have disputed it already.|Dos medios ya lo han cuestionado.",
  "A|So the whole story is false?|¿Entonces toda la noticia es falsa?",
  "B|Not false. Blown out of proportion.|Falsa no. Exagerada.",
  "A|There does seem to be a bias in the coverage.|Sí que parece haber un sesgo en la cobertura.",
  "B|Always worth reading the original report.|Siempre merece la pena leer el informe original."]},
 esc:[{q:"What is wrong with the headline?",o:["It is misleading","It is old","It is boring"],k:0},
      {q:"Where does the figure come from?",o:["An official report","An unnamed source","A survey"],k:1},
      {q:"Is the story false?",o:["Completely","Blown out of proportion","Verified"],k:1}],
 gram:{t:"Lenguaje de la evaluación crítica", idea:"Atribuir: <i>According to…, Sources suggest…, It has been reported that…</i> Cuestionar: <i>The claim has been disputed / There is no evidence to support…</i> Matizar: <i>misleading, exaggerated, selective, out of context</i>. Recuerda las pasivas impersonales del día 8: aquí se usan constantemente.",
  ej:["According to unnamed sources, the figure is double.","The claim has been widely disputed.","There is no evidence to support it.","The quotation was taken out of context.","The coverage is clearly selective.","It is worth checking the original source."],
  nota:"Distingue <i>fact</i> (verificable), <i>claim</i> (afirmación sin verificar) y <i>opinion</i>. En inglés periodístico la elección de una u otra palabra ya es una postura.",
  drill:[["___ to unnamed sources, the figure is double.","According"],["The claim has been widely ___ .","disputed"],["The quote was taken out of ___ .","context"],["The headline is ___ . (engañoso)","misleading"]]},
 prod:{habla:"Analiza en voz alta una noticia reciente: fuente, sesgo, lo verificable y lo exagerado.",
  escribe:"Escribe un análisis crítico de 6 frases sobre una noticia.",
  modelo:"The headline claiming that waiting lists have tripled is, at best, deeply misleading. The figure comes from an unnamed source and has already been disputed by two independent outlets. According to the original report, the increase applies to one specific speciality in one region. The story is not false, but it has clearly been blown out of proportion for political reasons. There is an evident bias in the way the coverage selects which figures to quote. Before sharing anything of this kind, it is always worth reading the original document.",
  tr:["El titular es engañoso.","The headline is misleading."]},
 test:[
  {q:"___ to unnamed sources, the figure is double.",o:["Accord","According","Accorded","In accord"],k:1},
  {q:"The claim has been widely ___ .",o:["disputed","disputing","dispute","disput"],k:0},
  {q:"'Misleading' significa…",o:["líder","engañoso","perdido","desviado del tema"],k:1},
  {q:"'Blown out of proportion' significa…",o:["explotado","exagerado","desproporcionado por error","soplado"],k:1},
  {q:"'Bias' significa…",o:["sesgo","base","bicho","diagonal"],k:0},
  {q:"'A claim' es…",o:["un hecho probado","una afirmación sin verificar","una queja legal solo","una opinión personal"],k:1},
  {q:"'Out of context' significa…",o:["fuera de contexto","sin contexto disponible","contextualizado","de otro tema"],k:0},
  {q:"'Outlet' en medios significa…",o:["salida","medio de comunicación","enchufe","tienda"],k:1}]
},
{
 d:24, tema:"Diplomacia profesional", objetivo:"Decir cosas difíciles sin romper la relación.",
 chunks:["I am not entirely convinced by that approach.","Would it be possible to reconsider the timeline?","With respect, the figures tell a different story.","I appreciate the constraints you are under.","Perhaps we could look at this differently.","I am afraid that would be difficult for us."],
 vocab:["constraint|limitación|The constraints we face.","reconsider|reconsiderar|Could you reconsider?","with respect|con todo el respeto|With respect, I disagree.","appreciate|comprender / valorar|I appreciate the difficulty.","not entirely|no del todo|Not entirely convinced.","raise a concern|plantear una preocupación|May I raise a concern?","common ground|puntos en común|Let us find common ground.","step back|dar un paso atrás|Let us step back.","revisit|volver sobre|Can we revisit this?","workable|viable|A workable solution."],
 dial:{t:"A difficult conversation with a client", l:[
  "A|We expect delivery by the fifteenth, as agreed.|Esperamos la entrega el día quince, como acordamos.",
  "B|I appreciate the pressure you are under.|Comprendo la presión que tienen.",
  "A|But?|¿Pero?",
  "B|I am afraid that date would now be difficult.|Me temo que esa fecha ahora sería difícil.",
  "A|That is not what we agreed.|Eso no es lo que acordamos.",
  "B|With respect, the specification changed in March.|Con todo el respeto, las especificaciones cambiaron en marzo.",
  "A|We were not told the impact.|No se nos informó del impacto.",
  "B|That is a fair point, and I take responsibility.|Es un apunte justo, y asumo la responsabilidad.",
  "A|So what do you propose?|¿Entonces qué propone?",
  "B|Perhaps we could revisit the scope and find something workable.|Quizá podríamos revisar el alcance y encontrar algo viable."]},
 esc:[{q:"What is the disagreement about?",o:["The price","The delivery date","The design"],k:1},
      {q:"What changed in March?",o:["The specification","The team","The budget"],k:0},
      {q:"What does B propose?",o:["Cancelling","Revisiting the scope","Paying a penalty"],k:1}],
 gram:{t:"Lenguaje diplomático", idea:"Tres técnicas: <b>negación atenuada</b> (<i>I am not entirely convinced</i> en vez de <i>I disagree</i>), <b>pregunta indirecta</b> (<i>Would it be possible to…?</i>) y <b>reconocimiento previo</b> (<i>I appreciate that… / That is a fair point, but…</i>). Los modales en pasado (<i>would, could, might</i>) suavizan sistemáticamente.",
  ej:["I am not entirely convinced by that approach.","Would it be possible to reconsider?","With respect, the figures differ.","I appreciate the constraints you are under.","That is a fair point, but…","I am afraid that would be difficult."],
  nota:"En inglés profesional, <i>That is interesting</i> y <i>with the greatest respect</i> pueden significar exactamente lo contrario de lo que dicen. La cortesía es el envoltorio, no el mensaje.",
  drill:[["I am not ___ convinced.","entirely"],["___ it be possible to reconsider?","Would"],["I ___ the constraints you are under.","appreciate"],["That is a ___ point, but…","fair"]]},
 prod:{habla:"Comunica en voz alta un retraso a un cliente enfadado sin perder la relación.",
  escribe:"Escribe un correo diplomático de 6 frases comunicando un problema.",
  modelo:"Dear Marta, thank you for your message and for setting out your concerns so clearly. I fully appreciate the pressure you are under with the opening scheduled for the fifteenth. I am afraid, however, that meeting that date would now be extremely difficult for us. With respect, the specification was substantially revised in March, and the impact on the programme was not reflected in the schedule. That said, I accept that we should have flagged the consequences at the time. Perhaps we could revisit the scope together this week and find a solution that works for both sides.",
  tr:["No estoy del todo convencido.","I am not entirely convinced."]},
 test:[
  {q:"I am not ___ convinced.",o:["complete","entirely","total","whole"],k:1},
  {q:"___ it be possible to reconsider?",o:["Will","Would","Do","Should"],k:1},
  {q:"'I appreciate the constraints' significa…",o:["Aprecio las restricciones estéticamente","Comprendo las limitaciones","Agradezco los límites","Valoro el precio"],k:1},
  {q:"'With respect, I disagree' suele preceder a…",o:["un acuerdo","un desacuerdo firme","una disculpa","una pregunta"],k:1},
  {q:"'That is a fair point' significa…",o:["Es un punto justo/válido","Es una feria","Es un precio justo","Es lo correcto"],k:0},
  {q:"'Workable' significa…",o:["trabajador","viable","laborable","funcional del todo"],k:1},
  {q:"'Revisit the scope' significa…",o:["visitar de nuevo","revisar el alcance","volver a ver","ampliar la vista"],k:1},
  {q:"'I am afraid that would be difficult' es…",o:["un miedo real","un no educado","un sí condicionado","una duda"],k:1}]
},
{
 d:25, tema:"Datos y tendencias", objetivo:"Describir gráficos y cifras con precisión.",
 chunks:["Sales peaked in March and then levelled off.","There was a steady increase over the period.","The figure stands at twelve per cent.","Numbers plummeted in the second quarter.","This accounts for roughly a third of the total.","The trend has reversed since June."],
 vocab:["peak|alcanzar el máximo|Sales peaked in March.","level off|estabilizarse|The curve levelled off.","plummet|desplomarse|Numbers plummeted.","steady|constante|A steady increase.","stand at|situarse en|The figure stands at 12%.","account for|representar|It accounts for a third.","fluctuate|fluctuar|Prices fluctuated wildly.","reverse|invertirse|The trend has reversed.","marginal|marginal|A marginal change.","roughly|aproximadamente|Roughly a third."],
 dial:{t:"Reading a chart together", l:[
  "A|What does the first graph show?|¿Qué muestra el primer gráfico?",
  "B|A steady increase in sales until March.|Un aumento constante de ventas hasta marzo.",
  "A|And after that?|¿Y después?",
  "B|They peaked and then levelled off.|Alcanzaron el máximo y luego se estabilizaron.",
  "A|What happened in the second quarter?|¿Qué pasó en el segundo trimestre?",
  "B|Numbers plummeted, mostly in the north.|Las cifras se desplomaron, sobre todo en el norte.",
  "A|How significant is that region?|¿Cuánto pesa esa región?",
  "B|It accounts for roughly a third of total revenue.|Representa aproximadamente un tercio de los ingresos.",
  "A|Where does the figure stand now?|¿En cuánto está la cifra ahora?",
  "B|At twelve per cent below last year, but the trend has reversed.|Un doce por ciento por debajo del año pasado, pero la tendencia se ha invertido."]},
 esc:[{q:"When did sales peak?",o:["January","March","June"],k:1},
      {q:"What share does the north represent?",o:["A tenth","Roughly a third","Half"],k:1},
      {q:"What is the current trend?",o:["Still falling","It has reversed","Flat"],k:1}],
 gram:{t:"Describir datos", idea:"Verbos: <b>rise, increase, grow, peak, level off, stabilise, fall, decline, drop, plummet, fluctuate, reverse</b>. Adverbios: <i>sharply, steadily, gradually, slightly, dramatically, marginally</i>. Fórmulas: <i>The figure stands at… / It accounts for… / There was a X% increase in… / compared with the same period last year</i>.",
  ej:["Sales rose sharply in the first quarter.","The curve levelled off in March.","Numbers plummeted after the price rise.","The figure stands at twelve per cent.","This accounts for roughly a third.","Compared with last year, output is down."],
  nota:"Sustantivo o verbo: <i>Sales increased sharply</i> = <i>There was a sharp increase in sales</i>. Alternar ambas construcciones es lo que da soltura en un informe.",
  drill:[["Sales ___ (peak) in March.","peaked"],["The curve levelled ___ .","off"],["The figure ___ at twelve per cent.","stands"],["It ___ for roughly a third.","accounts"]]},
 prod:{habla:"Describe en voz alta la evolución de un dato de tu trabajo o tu vida en los últimos cinco años.",
  escribe:"Escribe 6 frases describiendo una tendencia con cifras.",
  modelo:"Sales rose steadily during the first quarter and peaked in March at just over two million. After that they levelled off for six weeks before plummeting in the second quarter. The decline was concentrated in the northern region, which accounts for roughly a third of total revenue. Compared with the same period last year, output currently stands at twelve per cent lower. Prices fluctuated considerably throughout the summer, which makes the underlying trend hard to read. Encouragingly, the pattern appears to have reversed since June.",
  tr:["Las ventas alcanzaron su máximo en marzo.","Sales peaked in March."]},
 test:[
  {q:"Sales ___ in March and then fell.",o:["peaked","peak","peaking","were peak"],k:0},
  {q:"The curve levelled ___ .",o:["up","off","down","over"],k:1},
  {q:"The figure ___ at twelve per cent.",o:["stays","stands","sits on","puts"],k:1},
  {q:"It ___ for roughly a third of sales.",o:["counts","accounts","amounts","adds"],k:1},
  {q:"'Plummet' significa…",o:["subir con fuerza","desplomarse","estabilizarse","fluctuar"],k:1},
  {q:"'A steady increase' es un aumento…",o:["brusco","constante","mínimo","dudoso"],k:1},
  {q:"'Marginal' significa…",o:["marginal, muy pequeño","central","al margen de la ley","escrito al margen"],k:0},
  {q:"'The trend has reversed' significa…",o:["se ha invertido","se ha repetido","se ha revisado","se ha frenado"],k:0}]
},
{
 d:26, tema:"Cultura y crítica", objetivo:"Reseñar y valorar con vocabulario rico.",
 chunks:["The performance was utterly compelling.","The plot is somewhat predictable.","It is beautifully shot but emotionally hollow.","The pace drags in the second half.","It is not without flaws, but it works.","I would recommend it with reservations."],
 vocab:["compelling|absorbente|A compelling performance.","predictable|previsible|A predictable plot.","overrated|sobrevalorado|Utterly overrated.","underrated|infravalorado|A criminally underrated film.","pace|ritmo|The pace drags.","plot|argumento|The plot is thin.","hollow|hueco|Emotionally hollow.","stunning|impresionante|Stunning cinematography.","tedious|tedioso|A tedious first hour.","with reservations|con reservas|Recommended with reservations."],
 dial:{t:"After the cinema", l:[
  "A|What did you make of it?|¿Qué te pareció?",
  "B|Beautifully shot, but emotionally hollow.|Preciosamente rodada, pero emocionalmente hueca.",
  "A|I found the lead performance compelling.|A mí la interpretación protagonista me pareció absorbente.",
  "B|Agreed. She carries the whole film.|De acuerdo. Ella sostiene toda la película.",
  "A|The plot was rather predictable, though.|Aunque el argumento era bastante previsible.",
  "B|And the pace drags badly in the second half.|Y el ritmo se arrastra mucho en la segunda mitad.",
  "A|Would you recommend it?|¿La recomendarías?",
  "B|With reservations. It is not without flaws.|Con reservas. No está exenta de defectos.",
  "A|The critics loved it.|A la crítica le encantó.",
  "B|Frankly, I think it is overrated.|Sinceramente, creo que está sobrevalorada."]},
 esc:[{q:"What did B like?",o:["The plot","The cinematography and lead performance","The pace"],k:1},
      {q:"What is the main criticism?",o:["Predictable plot and slow pace","Bad acting","Poor sound"],k:0},
      {q:"Would B recommend it?",o:["Enthusiastically","With reservations","Never"],k:1}],
 gram:{t:"Adjetivos de valoración y matiz", idea:"Combina un elogio y una crítica en la misma frase: <i>beautifully shot but emotionally hollow</i>. Usa adverbios de valoración (<i>utterly, genuinely, somewhat, rather, criminally</i>) y suavizadores (<i>with reservations, not without flaws, I found it…</i>).",
  ej:["The performance was utterly compelling.","The plot is somewhat predictable.","It is not without flaws.","The pace drags in the second half.","It is criminally underrated.","I would recommend it with reservations."],
  nota:"<i>I found it boring</i> suena mucho más educado que <i>It was boring</i>: atribuye la opinión a tu experiencia, no al objeto. Es una marca clara de nivel alto.",
  drill:[["The performance was ___ compelling. (absolutamente)","utterly"],["The plot is ___ predictable. (un tanto)","somewhat"],["It is not ___ flaws.","without"],["I would recommend it with ___ .","reservations"]]},
 prod:{habla:"Reseña en voz alta una película o un libro en dos minutos: dos elogios, dos críticas y una recomendación matizada.",
  escribe:"Escribe una reseña de 6 frases.",
  modelo:"Visually, the film is stunning: it is beautifully shot and the score is genuinely memorable. The lead performance is utterly compelling and carries the whole story almost single-handedly. Unfortunately, the plot is somewhat predictable and the pace drags badly in the second half. I found the ending emotionally hollow, which is a shame after such a strong opening hour. It is not without flaws, but it is far from the disaster some critics have described. Overall I would recommend it with reservations, particularly to anyone who values atmosphere over story.",
  tr:["Lo recomendaría con reservas.","I would recommend it with reservations."]},
 test:[
  {q:"The performance was ___ compelling.",o:["very much","utterly","too","so much"],k:1},
  {q:"The plot is ___ predictable.",o:["somewhat","somewhere","some","somehow"],k:0},
  {q:"'Overrated' significa…",o:["sobrevalorado","muy valorado","calificado","tasado de más"],k:0},
  {q:"'The pace drags' significa…",o:["el ritmo se arrastra","el paso arrastra","la carrera tira","el ritmo acelera"],k:0},
  {q:"'Not without flaws' significa…",o:["sin defectos","no exento de defectos","con muchos defectos","perfecto"],k:1},
  {q:"'Hollow' significa…",o:["hueco","santo","completo","brillante"],k:0},
  {q:"¿Cuál suena más educado?",o:["It was boring.","I found it rather slow.","It is terrible.","Nobody liked it."],k:1},
  {q:"'Tedious' significa…",o:["tedioso","tedioso solo al final","técnico","tenso"],k:0}]
},
{
 d:27, tema:"Salud, hábitos y bienestar", objetivo:"Hablar de estilo de vida con nombres abstractos.",
 chunks:["There is growing awareness of mental health.","Burnout is increasingly common in this sector.","Sleep deprivation affects performance dramatically.","It is a question of striking a balance.","Prevention is cheaper than treatment.","The benefits are well documented."],
 vocab:["awareness|concienciación|Growing awareness.","burnout|desgaste profesional|Burnout is common.","deprivation|privación|Sleep deprivation.","strike a balance|encontrar el equilibrio|Strike a balance.","well-being|bienestar|Employee well-being.","sedentary|sedentario|A sedentary lifestyle.","cope with|sobrellevar|How do you cope with stress?","take its toll|pasar factura|Stress takes its toll.","moderation|moderación|Everything in moderation.","evidence-based|basado en evidencia|Evidence-based advice."],
 dial:{t:"Talking about workplace stress", l:[
  "A|Do you think burnout is taken seriously here?|¿Crees que aquí se toma en serio el desgaste profesional?",
  "B|There is growing awareness, but little action.|Hay más concienciación, pero poca acción.",
  "A|Has it affected the team?|¿Ha afectado al equipo?",
  "B|Two people were off last year. It takes its toll.|Dos personas estuvieron de baja el año pasado. Pasa factura.",
  "A|What would actually help?|¿Qué ayudaría de verdad?",
  "B|Fewer meetings and realistic deadlines.|Menos reuniones y plazos realistas.",
  "A|Not yoga at lunchtime, then?|¿No yoga a mediodía, entonces?",
  "B|That is the classic mistake. It is about workload.|Ese es el error clásico. Es cuestión de carga de trabajo.",
  "A|How do you cope personally?|¿Cómo lo llevas tú?",
  "B|I try to strike a balance. Some weeks better than others.|Intento encontrar el equilibrio. Unas semanas mejor que otras."]},
 esc:[{q:"What is the situation with burnout?",o:["Growing awareness, little action","Fully solved","Not discussed"],k:0},
      {q:"What would help according to B?",o:["Yoga","Fewer meetings and realistic deadlines","More holidays"],k:1},
      {q:"How does B cope?",o:["Trying to strike a balance","Working less","Changing jobs"],k:0}],
 gram:{t:"Nominalización", idea:"El registro formal convierte verbos y adjetivos en <b>sustantivos abstractos</b>: <i>aware → awareness, deprive → deprivation, treat → treatment, prevent → prevention, perform → performance, decide → decision</i>. Da densidad al texto: <i>People are increasingly aware</i> → <i>There is growing awareness</i>.",
  ej:["There is growing awareness of mental health.","Sleep deprivation affects performance.","Prevention is cheaper than treatment.","The implementation was delayed.","Her decision surprised everyone.","Improvement requires consistency."],
  nota:"Cuidado: abusar de la nominalización hace el texto pesado. Un buen B2 alterna frases nominales densas con frases verbales directas.",
  drill:[["aware → sustantivo:","awareness"],["treat → sustantivo:","treatment"],["prevent → sustantivo:","prevention"],["It is a question of ___ a balance.","striking"]]},
 prod:{habla:"Habla dos minutos sobre el estrés laboral: causas, consecuencias y soluciones reales.",
  escribe:"Escribe 6 frases sobre bienestar con sustantivos abstractos.",
  modelo:"There is growing awareness of burnout in our sector, although awareness rarely translates into action. Sleep deprivation and constant availability affect performance far more than most managers admit. Two colleagues were on long-term leave last year, which shows the toll that chronic overwork takes. The usual response is a wellness programme, when the real issue is workload and unrealistic deadlines. Prevention, in this case, would be considerably cheaper than treatment. Ultimately it is a question of striking a balance between output and sustainability.",
  tr:["Hay una creciente concienciación sobre la salud mental.","There is growing awareness of mental health."]},
 test:[
  {q:"El sustantivo de 'aware' es…",o:["awaring","awareness","awarement","awared"],k:1},
  {q:"El sustantivo de 'treat' es…",o:["treating","treatment","treatance","treatation"],k:1},
  {q:"It is a question of ___ a balance.",o:["strike","striking","struck","to striking"],k:1},
  {q:"'Take its toll' significa…",o:["cobrar peaje","pasar factura","tomar el control","llevarse todo"],k:1},
  {q:"'Burnout' significa…",o:["incendio","desgaste profesional","apagón","quemadura"],k:1},
  {q:"'Sedentary' significa…",o:["sedentario","sediento","sedante","estable"],k:0},
  {q:"'Cope with' significa…",o:["copiar","sobrellevar","cooperar","enfrentarse violentamente"],k:1},
  {q:"'Evidence-based' significa…",o:["basado en pruebas","evidente","con base legal","obvio"],k:0}]
},
{
 d:28, tema:"REPASO · Discusión abstracta", objetivo:"Sostener la parte 3 de un examen oral B2.",
 chunks:["That is an interesting question. Let me think.","It very much depends on the context.","I suppose the underlying issue is…","There are two ways of looking at this.","If I had to generalise, I would say…","Historically, that has not been the case."],
 vocab:["underlying|subyacente|The underlying issue.","generalise|generalizar|If I had to generalise.","historically|históricamente|Historically speaking.","in principle|en principio|In principle, yes.","in practice|en la práctica|In practice, rarely.","a case in point|un buen ejemplo|A case in point is Spain.","to a large extent|en gran medida|True to a large extent.","the flip side|la otra cara|The flip side is cost.","in the grand scheme|en el conjunto|In the grand scheme of things.","by definition|por definición|By definition, it is limited."],
 dial:{t:"Speaking exam, part three", l:[
  "A|Do you think technology has improved education?|¿Cree que la tecnología ha mejorado la educación?",
  "B|That is an interesting question. It depends on the context.|Es una pregunta interesante. Depende del contexto.",
  "A|In what way?|¿En qué sentido?",
  "B|In principle it widens access. In practice, not always.|En principio amplía el acceso. En la práctica, no siempre.",
  "A|Could you give an example?|¿Podría dar un ejemplo?",
  "B|Rural schools are a case in point.|Las escuelas rurales son un buen ejemplo.",
  "A|And the flip side?|¿Y la otra cara?",
  "B|Distraction, and a widening gap between homes.|La distracción y una brecha creciente entre hogares.",
  "A|Will this change in the future?|¿Cambiará esto en el futuro?",
  "B|Historically, technology has never closed a social gap by itself.|Históricamente, la tecnología nunca ha cerrado sola una brecha social."]},
 esc:[{q:"What is B's overall position?",o:["Technology always helps","It depends on the context","Technology is harmful"],k:1},
      {q:"What example does B give?",o:["Rural schools","City universities","Online courses"],k:0},
      {q:"What is the downside mentioned?",o:["Cost","Distraction and inequality","Speed"],k:1}],
 gram:{t:"Discurso abstracto", idea:"Recursos para responder a preguntas generales: ganar tiempo (<i>That is an interesting question…</i>), matizar (<i>It depends on…, In principle… in practice…</i>), ejemplificar (<i>A case in point is…</i>), contrastar (<i>The flip side is…</i>) y generalizar con cautela (<i>If I had to generalise…, Broadly speaking…</i>).",
  ej:["That is an interesting question.","It very much depends on the context.","In principle yes, in practice rarely.","A case in point is rural education.","The flip side is the cost.","Historically, that has not been the case."],
  nota:"En la parte 3 del examen no se valora tener razón, sino <b>desarrollar</b>: una respuesta de una sola frase baja la nota aunque sea correcta. Responde, matiza y ejemplifica siempre.",
  drill:[["It very much ___ on the context.","depends"],["In principle yes, in ___ rarely.","practice"],["A case in ___ is rural education.","point"],["If I had to ___ , I would say yes.","generalise"]]},
 prod:{habla:"Responde durante dos minutos a: «¿Ha mejorado la tecnología la educación?» con matiz, ejemplo y contraejemplo.",
  escribe:"Escribe una respuesta desarrollada de 8 frases a una pregunta abstracta.",
  modelo:"That is a genuinely interesting question, and I think the answer depends very much on the context. In principle, technology widens access to education enormously; in practice, the results are far more uneven. A case in point is rural schools, where a single connection can replace an entire missing library. The flip side is distraction, and a widening gap between households that can support learning and those that cannot. If I had to generalise, I would say the tool amplifies whatever inequality already exists. Historically, no technology has closed a social gap on its own, and there is little reason to expect this one to be different. That said, the pandemic showed that resistance to change was mostly cultural rather than technical. In the grand scheme of things, what matters is teaching, not the device it arrives on.",
  tr:["Depende mucho del contexto.","It very much depends on the context."]},
 test:[
  {q:"It very much ___ on the context.",o:["depend","depends","is depending","depended"],k:1},
  {q:"In principle yes, in ___ rarely.",o:["practise","practice","practical","practicing"],k:1},
  {q:"'A case in point' significa…",o:["un caso puntual","un buen ejemplo","un caso perdido","un punto de caso"],k:1},
  {q:"'The flip side' significa…",o:["la otra cara","el lado que se voltea","el reverso legal","la parte mala solo"],k:0},
  {q:"'If I had to generalise' sirve para…",o:["afirmar tajantemente","generalizar con cautela","preguntar","concluir"],k:1},
  {q:"'Underlying issue' significa…",o:["asunto subyacente","asunto menor","asunto pendiente","asunto último"],k:0},
  {q:"'To a large extent' significa…",o:["en gran medida","de gran extensión","hasta el largo","con amplitud"],k:0},
  {q:"En la parte 3 conviene…",o:["responder con una frase","desarrollar y ejemplificar","evitar opinar","hablar rapidísimo"],k:1}]
},
{
 d:29, tema:"Matices de significado", objetivo:"Distinguir sinónimos y connotaciones.",
 chunks:["He is not stubborn, he is determined.","There is a difference between cheap and inexpensive.","She is assertive rather than aggressive.","It was a mistake, not a lie.","The word carries negative connotations.","That is a euphemism for redundancy."],
 vocab:["connotation|connotación|Negative connotations.","euphemism|eufemismo|A euphemism for firing.","subtle|sutil|A subtle difference.","interchangeable|intercambiable|They are not interchangeable.","derogatory|despectivo|A derogatory term.","neutral|neutro|A neutral word.","imply|dar a entender|That implies blame.","denote|denotar|It denotes quantity.","loaded|cargado|A loaded question.","precise|preciso|Be more precise."],
 dial:{t:"Choosing the right word", l:[
  "A|Would you describe him as stubborn?|¿Lo describirías como testarudo?",
  "B|I would say determined. It is less derogatory.|Yo diría decidido. Es menos despectivo.",
  "A|Is there really a difference?|¿Hay diferencia de verdad?",
  "B|The meaning is similar; the connotation is not.|El significado es parecido; la connotación no.",
  "A|Like cheap and inexpensive?|¿Como cheap e inexpensive?",
  "B|Exactly. Cheap can imply poor quality.|Exacto. Cheap puede dar a entender mala calidad.",
  "A|And assertive versus aggressive?|¿Y assertive frente a aggressive?",
  "B|One is a virtue, the other a warning.|Una es una virtud, la otra una advertencia.",
  "A|Companies love those distinctions.|A las empresas les encantan esas distinciones.",
  "B|Indeed. Restructuring is a euphemism for redundancies.|Efectivamente. Reestructuración es un eufemismo por despidos."]},
 esc:[{q:"What word does B prefer to 'stubborn'?",o:["Difficult","Determined","Firm"],k:1},
      {q:"What can 'cheap' imply?",o:["Poor quality","Good value","Luxury"],k:0},
      {q:"What is 'restructuring' a euphemism for?",o:["Promotions","Redundancies","Training"],k:1}],
 gram:{t:"Connotación y precisión léxica", idea:"Los sinónimos rara vez son intercambiables: <i>slim / thin / skinny</i>, <i>confident / arrogant</i>, <i>determined / stubborn</i>, <i>inexpensive / cheap</i>, <i>curious / nosy</i>, <i>frugal / stingy</i>. La diferencia no está en el significado (<b>denotation</b>) sino en la actitud que transmite (<b>connotation</b>).",
  ej:["He is determined rather than stubborn.","She is slim, not skinny.","He is confident, some would say arrogant.","It is inexpensive rather than cheap.","That is a loaded question.","Restructuring is a euphemism for redundancies."],
  nota:"Truco para exámenes: cuando dudes entre dos sinónimos, elige el neutro. El adjetivo con carga negativa siempre es la opción arriesgada.",
  drill:[["Positivo de 'stubborn':","determined"],["Positivo de 'skinny':","slim"],["Positivo de 'cheap':","inexpensive"],["'Restructuring' es un ___ por despidos.","euphemism"]]},
 prod:{habla:"Describe a tres personas dos veces: primero con adjetivos favorables y luego con sus equivalentes negativos.",
  escribe:"Escribe 6 frases contrastando pares de sinónimos con distinta connotación.",
  modelo:"I would describe my colleague as determined rather than stubborn, although the behaviour is identical. There is a real difference between calling a hotel inexpensive and calling it cheap: the second implies poor quality. She is assertive in meetings, which some older managers still choose to call aggressive. Being curious about a project is admirable; being nosy about a colleague's salary is not. When a company announces a restructuring, everyone understands it is a euphemism for redundancies. Choosing the neutral word is not dishonesty; it is precision.",
  tr:["No es testarudo, es decidido.","He is not stubborn, he is determined."]},
 test:[
  {q:"Versión positiva de 'stubborn':",o:["obstinate","determined","rigid","difficult"],k:1},
  {q:"Versión positiva de 'skinny':",o:["thin","bony","slim","frail"],k:2},
  {q:"'Cheap' frente a 'inexpensive' implica…",o:["mejor calidad","posible mala calidad","lo mismo","más caro"],k:1},
  {q:"'A euphemism' es…",o:["una exageración","un término suavizado","un insulto","una metáfora"],k:1},
  {q:"'Derogatory' significa…",o:["despectivo","derogado","obligatorio","derivado"],k:0},
  {q:"'A loaded question' es una pregunta…",o:["larga","cargada, tendenciosa","cargada de datos","pesada"],k:1},
  {q:"'Imply' significa…",o:["implicar / dar a entender","implorar","emplear","aplicar"],k:0},
  {q:"'Nosy' significa…",o:["ruidoso","cotilla","narigudo","curioso en buen sentido"],k:1}]
},
{
 d:30, tema:"Consolidación B2", objetivo:"Cerrar los 90 días y prepararte para el examen final.",
 chunks:["Three months ago I could not have had this conversation.","What has changed most is my confidence.","I no longer translate; I think in English.","Had I known it was this achievable, I would have started earlier.","The next step is maintaining the level.","It is a habit now, not a course."],
 vocab:["achievable|alcanzable|It is perfectly achievable.","maintain|mantener|Maintain the level.","plateau|estancamiento|Progress hits a plateau.","consolidate|consolidar|Consolidate what you know.","expose yourself to|exponerse a|Expose yourself to real English.","immerse|sumergirse|Immerse yourself in it.","keep up|mantener el ritmo|Keep it up.","fall behind|quedarse atrás|Do not fall behind.","milestone|hito|A major milestone.","from now on|de ahora en adelante|From now on, no subtitles."],
 dial:{t:"Ninety days later", l:[
  "A|So, ninety days. Was it worth it?|Bueno, noventa días. ¿Mereció la pena?",
  "B|Three months ago I could not have had this conversation.|Hace tres meses no habría podido tener esta conversación.",
  "A|What has changed most?|¿Qué ha cambiado más?",
  "B|My confidence. And I no longer translate in my head.|Mi confianza. Y ya no traduzco mentalmente.",
  "A|Any regrets?|¿Algún arrepentimiento?",
  "B|Had I known it was this achievable, I would have started years ago.|Si hubiera sabido que era tan alcanzable, habría empezado hace años.",
  "A|What is the risk now?|¿Cuál es el riesgo ahora?",
  "B|Hitting a plateau and falling behind.|Estancarme y quedarme atrás.",
  "A|So what is the plan?|¿Y cuál es el plan?",
  "B|Keep it up: reading, series without subtitles, and speaking weekly.|Mantenerlo: lectura, series sin subtítulos y hablar cada semana."]},
 esc:[{q:"What has changed most for B?",o:["Grammar","Confidence and no mental translation","Vocabulary only"],k:1},
      {q:"What does B regret?",o:["Not starting earlier","Starting at all","The method"],k:0},
      {q:"What is the plan now?",o:["Stop studying","Reading, series and weekly speaking","Take another course"],k:1}],
 gram:{t:"Mapa del nivel B2", idea:"Este mes has cubierto: <b>tercer condicional y mixtos, wish/if only, modales perfectos, inversión enfática, cleft sentences, cláusulas de participio, pasivas impersonales, verbos de reporte con patrón, relativas complejas, futuros formales, hedging, marcadores del habla, registro, especulación, concesión, nominalización y connotación</b>. Eso es un B2 sólido y con criterio.",
  ej:["Had I known, I would have started earlier.","I wish I had begun years ago.","Never have I made so much progress.","What matters most is consistency.","Having finished the course, I need a new habit.","It is arguably the best investment I have made."],
  nota:"Después del B2 el enemigo no es la gramática: es el <b>estancamiento</b>. Sin exposición diaria, un B2 se degrada a B1 en un año. El plan de mantenimiento importa tanto como el curso.",
  drill:[["___ I known, I would have started earlier.","Had"],["I ___ I had begun years ago.","wish"],["Never ___ I made so much progress.","have"],["___ matters most is consistency.","What"]]},
 prod:{habla:"Haz un balance de los noventa días en dos minutos y expón tu plan de mantenimiento para los próximos seis meses.",
  escribe:"Escribe un balance final de 10 frases.",
  modelo:"Three months ago I could not have held a conversation like this one, let alone written this paragraph. What has changed most is not my grammar but my confidence: I no longer rehearse sentences before saying them. I have stopped translating in my head, which is the single biggest difference between B1 and B2. Had I known that ninety consecutive days would be enough to get here, I would have started years ago. Never have I been so consistent with anything outside work. The real risk now is hitting a plateau and slowly falling behind. From now on, the plan is simple: one series a week without subtitles, one book a month and one conversation a week with a real person. I intend to consolidate rather than to rush towards C1. It is a habit now, not a course, and that is the point. Ultimately, the method mattered less than the fact that I did not miss a day.",
  tr:["Ya no traduzco; pienso en inglés.","I no longer translate; I think in English."]},
 test:[
  {q:"___ I known, I would have started earlier.",o:["If","Had","Would","Should"],k:1},
  {q:"I wish I ___ years ago.",o:["began","had begun","would begin","begin"],k:1},
  {q:"Never ___ I made so much progress.",o:["did","have","had","am"],k:1},
  {q:"___ matters most is consistency.",o:["That","What","Which","It"],k:1},
  {q:"It is ___ the best investment I have made.",o:["arguable","arguably","argued","arguing"],k:1},
  {q:"'Hit a plateau' significa…",o:["estancarse","llegar a la cima","golpear","subir de nivel"],k:0},
  {q:"'Keep it up' significa…",o:["mantenerlo / seguir así","guardarlo arriba","levantarlo","aguantar"],k:0},
  {q:"'Achievable' significa…",o:["alcanzable","logrado","archivable","aceptable"],k:0}]
}
];
